window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-27"]={"date": "2026-08-27", "dateKR": "2026년 8월 27일", "dateEN": "27 August 2026", "total": 112, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "Davie, 캐나다 해안경비대용 쇄빙선 6척 80억 달러 건조계약 확보", "src": "gCaptain", "date": "2026-08-27", "kSum": "캐나다 조선사 다비(Davie)가 캐나다 해안경비대(Canadian Coast Guard)를 위한 신형 쇄빙선 6척을 건조하는 80억 달러 규모의 고정가 계약을 공식 체결했다. 이는 북극권 조선 포트폴리오 확대의 일환으로 세부 내용이 새로 공개됐다.", "eSum": "Canadian shipbuilder Davie has formally secured an US$8 billion fixed-price contract to build six new icebreakers for the Canadian Coast Guard, adding to its growing Arctic shipbuilding portfolio.", "kImp": "북극 항로 경쟁이 가속되는 가운데 서방권 쇄빙선 건조 역량 확충을 보여주는 대형 계약으로, 극지 조선 시장의 판도 변화를 시사한다.", "eImp": "A landmark deal underscoring Western icebreaker construction capacity amid an accelerating Arctic shipping race.", "url": "https://gcaptain.com/davie-adds-six-canadian-icebreakers-to-growing-arctic-shipbuilding-portfolio/"}, {"code": "TOP", "title": "CMA CGM, 사우디 제다항 4억3400만 달러 확장 사업 참여", "src": "gCaptain", "date": "2026-08-27", "kSum": "홍해게이트웨이터미널(Red Sea Gateway Terminal)과 CMA CGM 그룹이 사우디아라비아 제다이슬람항(Jeddah Islamic Port)에 신규 컨테이너 터미널을 개발하기 위해 초기 4억3400만 달러를 투자하기로 합의했다.", "eSum": "Red Sea Gateway Terminal and CMA CGM Group have agreed to invest an initial $434 million to develop a new container terminal at Saudi Arabia's Jeddah Islamic Port.", "kImp": "홍해 물류 정상화 기대 속에 주요 선사가 사우디 항만 인프라에 대규모 투자를 단행하며 중동 환적 허브 경쟁이 재점화되고 있다.", "eImp": "A major carrier commits heavy capital to Saudi port infrastructure, reigniting Middle East transhipment hub competition.", "url": "https://gcaptain.com/cma-cgm-joins-434-million-expansion-of-saudi-arabias-jeddah-port/"}, {"code": "TOP", "title": "회그 오토라이너스, 오로라급 자동차운반선 6척 추가 발주", "src": "gCaptain", "date": "2026-08-26", "kSum": "회그 오토라이너스(Höegh Autoliners)가 중국에서 9,100 CEU급 오로라(Aurora)급 자동차운반선(PCTC) 6척을 추가 발주하며 시리즈를 총 18척으로 확대했다. 자금 조달을 위해 주주 대상 14억2000만 노르웨이크로네(약 1억5200만 달러) 증자도 병행한다.", "eSum": "Höegh Autoliners has ordered six more 9,100 ceu Aurora-class car carriers in China, taking the series to 18 vessels, and is raising NOK1.42bn ($152m) from shareholders to help fund the expansion.", "kImp": "자동차 해상운송 수요 회복과 친환경 선대 교체 흐름 속에서 PCTC 신조 발주가 이어지고 있음을 보여준다.", "eImp": "Signals continued PCTC newbuilding momentum amid car-carrying demand and green fleet renewal.", "url": "https://gcaptain.com/hoegh-autoliners-orders-six-more-aurora-class-car-carriers/"}, {"code": "TOP", "title": "SK가스, 파나마운하 통항권 경매서 사상 최고 530만 달러 지불", "src": "Splash247", "date": "2026-08-26", "kSum": "SK가스(SK Gas)가 파나마운하 통항 순번을 확보하기 위해 사상 최고액인 530만 달러를 경매에서 지불했다. 예약 없이 운하에 몰린 선박이 급증하며 경매가가 평소의 최대 9배까지 치솟고 있다.", "eSum": "SK Gas paid a record $5.3m at auction to secure a Panama Canal transit slot, as a surge in unreserved ships pushes auction prices to as much as nine times the normal level.", "kImp": "장기화가 우려되는 엘니뇨발 가뭄·물 부족 속에 운하 통항 비용 급등이 가스·에너지 물류비 부담으로 직결되고 있다.", "eImp": "Soaring transit costs amid drought concerns translate directly into higher gas and energy logistics expenses.", "url": "https://splash247.com/sk-gas-pays-record-5-3m-to-jump-panama-canal-queue/"}, {"code": "TOP", "title": "홍해 컨테이너 운송, 연말까지 정상화 전망", "src": "Splash247", "date": "2026-08-26", "kSum": "업계 분석에 따르면 홍해를 경유하는 컨테이너 해운이 연말까지 정상화될 것으로 전망됐다. 우회 운항이 장기화됐던 주요 항로에서 통항 재개 기대가 커지고 있다.", "eSum": "Container shipping through the Red Sea is tipped to normalise by year-end, raising expectations of a return to the key route after prolonged diversions.", "kImp": "홍해 항로 복귀는 운임·선복 수급 및 유럽-아시아 리드타임에 광범위한 영향을 미칠 핵심 변수다.", "eImp": "A Red Sea return would broadly reshape freight rates, capacity balance and Asia-Europe lead times.", "url": "https://splash247.com/container-shipping-tipped-to-normalise-through-red-sea-by-year-end/"}, {"code": "TOP", "title": "ADNOC L&S, LNG선 신조 프로그램 추가 확대", "src": "Splash247", "date": "2026-08-26", "kSum": "아부다비국영석유 물류·해운 부문인 ADNOC L&S(ADNOC Logistics & Services)가 LNG 운반선 2척에 대한 옵션을 추가 행사하며 신조 프로그램을 확대했다.", "eSum": "ADNOC Logistics & Services has exercised options for two more LNG carriers, expanding its newbuilding programme.", "kImp": "중동 산유국의 LNG 수출 물류 자립 강화 흐름을 보여주며 LNG선 신조 수요를 뒷받침한다.", "eImp": "Reflects Gulf producers' drive to build in-house LNG shipping capacity, underpinning LNG carrier newbuild demand.", "url": "https://splash247.com/adnoc-ls-lifts-lng-newbuild-programme/"}, {"code": "TOP", "title": "닝보-저우산항, 싱가포르 제치고 세계 2위 컨테이너항 등극", "src": "Seatrade Maritime", "date": "2026-08-26", "kSum": "중국 닝보-저우산항(Ningbo-Zhoushan)이 컨테이너 물동량에서 싱가포르를 제치고 세계 2위 컨테이너항으로 올라섰다.", "eSum": "China's Ningbo-Zhoushan has overtaken Singapore to become the world's second-largest container port by throughput.", "kImp": "글로벌 항만 순위 재편은 중국 항만의 물동량 집중과 환적 허브 경쟁 구도 변화를 상징한다.", "eImp": "A reshuffle of global port rankings highlights China's throughput concentration and shifting transhipment competition.", "url": "https://www.seatrade-maritime.com/ports-logistics/ningbo-zhoushan-overtakes-singapore-as-second-largest-container-port"}, {"code": "TOP", "title": "이란·오만, 호르무즈 해협 관리 위한 임시 통항 프레임워크 발표", "src": "gCaptain", "date": "2026-08-25", "kSum": "이란과 오만이 호르무즈 해협(Strait of Hormuz)의 안전 항행 복원을 위한 프레임워크를 공개했다. 임시 통항 회랑, 공동 항행 및 기뢰 제거 협력 등을 포함하며 약 6개월간 봉쇄됐던 해협의 관리 방안을 담았다.", "eSum": "Iran and Oman have unveiled a framework for restoring safe navigation through the Strait of Hormuz, including a temporary shipping corridor and joint mine-clearance cooperation after nearly six months of blockade.", "kImp": "세계 최대 원유 수송 요충지의 통항 재개 논의는 유가·탱커 시장과 에너지 안보에 결정적 영향을 미친다.", "eImp": "Talks to reopen the world's key oil chokepoint are pivotal for crude prices, the tanker market and energy security.", "url": "https://gcaptain.com/iran-and-oman-unveil-framework-for-future-management-of-strait-of-hormuz/"}, {"code": "TOP", "title": "닝보마린, 벌크선 5척 신조로 선대 확장 추진", "src": "Splash247", "date": "2026-08-26", "kSum": "상하이 상장사 닝보마린(Ningbo Marine)이 중국에서 벌크선 5척을 추가 신조해 약 60만 dwt의 신규 선복을 더하는 선대 교체 프로그램을 추진한다. 저장에너지(Zhejiang Energy)가 후원하며 최대 9억8000만 위안을 승인했다.", "eSum": "Shanghai-listed Ningbo Marine is lining up five more bulk carrier newbuildings in China, adding close to 600,000 dwt, with backer Zhejiang Energy approving up to CNY980m.", "kImp": "중국 선주들의 벌크 선대 교체 발주가 이어지며 신조 시장과 드라이벌크 선복 수급에 영향을 준다.", "eImp": "Continued Chinese bulker renewal orders affect the newbuilding market and dry bulk capacity balance.", "url": "https://splash247.com/ningbo-marine-maps-out-five-ship-bulker-expansion/"}, {"code": "TOP", "title": "트럼프 행정부, 해운·석유 겨냥 대이란 전방위 신규 제재 개시", "src": "gCaptain", "date": "2026-08-24", "kSum": "트럼프 행정부가 이란을 겨냥한 대규모 경제 압박 캠페인을 개시하며 해운 부문으로 2차 제재 위협을 확대했다. 이란과 거래하는 국가·기업에 대한 처벌을 경고했다.", "eSum": "The Trump administration has launched a sweeping economic campaign against Iran, expanding the threat of secondary sanctions to the shipping sector and warning of penalties for those trading with Tehran.", "kImp": "그림자 선단·탱커 운항과 이란 원유 교역에 광범위한 준법·보험 리스크를 확산시켜 글로벌 해운에 파장을 준다.", "eImp": "Broadens compliance and insurance risk across shadow-fleet tanker trades and Iranian oil flows, rippling through global shipping.", "url": "https://gcaptain.com/trump-administration-launches-sweeping-new-iran-sanctions-campaign-targeting-shipping-and-oil-trade/"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "파나마 선적 벌크선 오션위너, 벵골만서 침몰…선원 22명 실종", "src": "gCaptain", "date": "2026-08-26", "kSum": "파나마 선적 벌크선 오션위너(Ocean Winner)가 벵골만(Bay of Bengal)에서 침몰해 선원 22명이 실종됐다. 인도 파라딥(Paradip)에서 8월 20일 철광석 미분 약 7만2000톤을 싣고 출항했으며, 파라딥 남동쪽 약 230해리 지점에서 조난신호 후 연락이 두절됐다. 인도 해경과 인근 상선이 참여한 대규모 수색이 진행됐고 탱커 아이소포스(Aisopos)가 생존자 2명을 구조했다. 선원 24명은 중국인 20명, 미얀마인 3명, 방글라데시인 1명으로 구성됐다.", "eSum": "The Panama-flagged bulk carrier Ocean Winner sank in the Bay of Bengal, leaving 22 seafarers missing. It had sailed from Paradip, India on August 20 with about 72,000 tonnes of iron ore fines and lost contact roughly 230 nautical miles southeast of Paradip. The tanker Aisopos rescued two survivors; the 24 crew were 20 Chinese, three Myanmar and one Bangladeshi national.", "kCause": "침몰 원인은 공식적으로 규명되지 않았다. 다만 액상화(liquefaction)가 발생하기 쉬운 철광석 미분 화물의 위험이 재조명됐으며, 화물 액상화로 인한 급격한 복원성 상실이 원인으로 추정된다(추정).", "eCause": "No official cause has been determined; attention has focused on the liquefaction risk of iron ore fines, with a sudden loss of stability from cargo liquefaction presumed as a possible cause (presumed).", "kLes": "철광석 미분·니켈광·보크사이트 등 액상화 취약 화물은 특히 우천 적재 시 극도의 주의가 필요하며, 수분 함량 및 TML 기준 준수와 적재 관리가 필수적이다. INTERCARGO는 액상화를 벌크선 부문 최대 인명 위험으로 경고해 왔다.", "eLes": "Cargoes prone to liquefaction (iron ore fines, nickel ore, bauxite) demand extreme caution, especially when loaded in wet conditions; strict moisture/TML compliance and load management are essential. INTERCARGO has warned liquefaction remains the deadliest hazard in the bulk sector.", "url": "https://gcaptain.com/ocean-winner-sinking-leaves-22-seafarers-missing-in-bay-of-bengal/"}, {"code": "ACC", "title": "고철 운반 벌크선 페더럴웰랜드, 카디프항서 화재", "src": "SAFETY4SEA", "date": "2026-08-26", "kSum": "마셜제도 선적 벌크선 페더럴웰랜드(Federal Welland)가 8월 25일 영국 카디프(Cardiff)의 퀸알렉산드라 부두(Queen Alexandra Docks)에서 화재가 발생했다. 당시 선박은 고철 약 2만 톤을 싣고 있었다. 사우스웨일스 소방구조대(SWFRS)가 구조정, 고가 소방차, 소방 예인선, 드론 등을 투입해 진화에 나섰으며 선원 전원은 안전한 것으로 확인됐다. 당국은 카디프만 일대에 다량의 연기가 간헐적으로 발생할 수 있다고 경고했다.", "eSum": "A fire broke out aboard the Marshall Islands-flagged bulk carrier Federal Welland at Queen Alexandra Docks in Cardiff, UK, on August 25 while it carried about 20,000 tonnes of scrap metal. South Wales Fire and Rescue Service deployed rescue tenders, an aerial platform, a firefighting tug and a drone; all crew were accounted for and safe.", "kCause": "화재의 정확한 발화 원인은 발표되지 않았다. 고철 화물 내 잔류물이나 자연발화 가능성 등 고철 적재 화물 특유의 화재 위험이 배경으로 추정된다(추정).", "eCause": "The exact ignition source was not disclosed; the fire-prone nature of scrap-metal cargo (residues, potential self-heating) is a presumed background factor (presumed).", "kLes": "고철 등 화재 위험 화물은 적재 전 이물질·인화성 잔류물 점검과 적재 중 감시가 중요하며, 항내 화재 시 신속한 소방 당국·항만 공동 대응 체계가 인명·환경 피해를 최소화한다.", "eLes": "Fire-prone cargoes such as scrap metal require pre-loading screening for flammable residues and monitoring during loading; rapid joint fire-service and port response in harbour limits casualties and environmental harm.", "url": "https://safety4sea.com/fire-breaks-out-on-vessel-carrying-scrap-metal-in-cardiff/"}, {"code": "ACC", "title": "러시아, 우크라이나 흑해 항만서 선박 5척 타격", "src": "MarineLink", "date": "2026-08-25", "kSum": "러시아 국방부는 흑해 피우덴니(Pivdennyi, 유즈니)항에서 우크라이나 군수품을 실은 화물선 3척과 탱커 1척을, 인근 오데사(Odesa)항에서 화물선 1척을 타격했다고 밝혔다. 또한 피우덴니·오데사의 항만 시설과 초르노모르스크(Chornomorsk)항의 연료 저장시설도 공격했다고 주장했다. 로이터는 이 주장을 독립적으로 확인하지 못했다.", "eSum": "Russia's Defence Ministry said its forces struck three cargo vessels carrying supplies for Ukraine's military and a tanker at the Black Sea port of Pivdennyi, plus another cargo vessel at Odesa, as well as port infrastructure and fuel storage at Chornomorsk. Reuters could not independently verify the claims.", "kCause": "군사 공격(미사일·드론 등)에 의한 피해로, 흑해 항만을 겨냥한 전시 무력 공격이 직접 원인이다.", "eCause": "Damage caused by a wartime military strike (missiles/drones) directly targeting Black Sea ports.", "kLes": "흑해 항만 기항 선박은 전쟁위험(war risk)이 상존하므로 전쟁보험, 정박 위치·시간 최소화, 실시간 위협 정보 공유 및 비상 대피 계획이 필수적이다.", "eLes": "Vessels calling at Black Sea ports face persistent war risk; war-risk insurance, minimising berth exposure, real-time threat sharing and evacuation planning are essential.", "url": "https://www.marinelink.com/news/russia-strikes-five-vessels-ports-along-542427"}, {"code": "ACC", "title": "후티, 사우디 얀부 인근 홍해서 바흐리 선박 '암잔' 공격", "src": "MarineLink", "date": "2026-08-24", "kSum": "예멘의 친이란 후티(Houthi) 반군이 홍해 사우디아라비아 얀부(Yanbu) 인근 해상에서 선박을 공격했다. 사우디 국영선사 바흐리(Bahri)는 자사 선박 '암잔(Amzan)'이 관련된 해상 사고가 있었으나 선원 전원이 안전하고 부상자는 없다고 밝혔다. 영국 해사무역기구(UKMTO)는 얀부 서쪽 약 63해리 지점에서 탱커가 미상의 발사체에 피격됐으며 선원 전원 안전, 환경 피해는 보고되지 않았다고 전했다.", "eSum": "Yemen's Iran-aligned Houthis attacked a vessel off Saudi Arabia's Red Sea port of Yanbu. Saudi state carrier Bahri said its vessel Amzan was involved in a maritime incident but all crew were safe with no injuries. UKMTO said a tanker was struck by an unknown projectile about 63nm west of Yanbu, with all crew safe and no environmental impact.", "kCause": "후티 반군의 발사체(미사일·드론 등) 공격에 의한 피격으로, 홍해 내 사우디 연계 선박을 겨냥한 전시 무력 공격이 원인이다.", "eCause": "Struck by a Houthi projectile (missile/drone) attack targeting Saudi-linked shipping in the Red Sea.", "kLes": "후티의 사우디 연계 선박 봉쇄 선언 이후 얀부·홍해 항로의 위협이 지속되므로 선박 식별정보 관리, 우회 항로 검토, UKMTO 보고 및 무력공격 대비 절차 점검이 요구된다.", "eLes": "With the Houthi blockade on Saudi-linked ships, threats persist on Yanbu/Red Sea routes; managing vessel identity data, considering rerouting, UKMTO reporting and attack-response drills are advised.", "url": "https://www.marinelink.com/news/houthis-attacked-vessel-offshore-saudi-542379"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "최근 7일간 신규 소식이 확인되지 않았습니다", "src": "—", "date": "2026-08-27", "kSum": "이 기간 신선 기사가 확인되지 않았습니다. 다음 갱신 시 보완됩니다.", "eSum": "No fresh items in the last 7 days; will be updated next cycle.", "kImp": "-", "eImp": "-", "url": "https://brightatsea-alt.github.io/maritime-daily-digest/"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "Höegh Autoliners lines up more car carriers", "src": "Splash247", "date": "2026-08-26", "kSum": "회그 오토라이너스(Höegh Autoliners)가 중국 차이나머천트중공업(China Merchants Heavy Industry)에 9,100 CEU급 LNG 이중연료 오로라(Aurora)급 자동차운반선 6척을 추가 발주해 확정 선대를 12척에서 18척으로 늘렸다. 동사는 옵션 4척과 슬롯 예약 4척을 확보해 최대 26척까지 확대할 수 있으며, 발주 직후 8.5백만 주 유상증자로 NOK14.2억(1.52억 달러)을 조달했다.", "eSum": "Höegh Autoliners ordered another six 9,100 CEU LNG dual-fuel Aurora-class car carriers at China Merchants Heavy Industry, lifting its firm programme from 12 to 18 ships. With options for four more and reservations for another four slots, the series could reach 26 vessels; the owner also raised NOK1.42bn ($152m) via an accelerated share placement to help fund the expansion.", "kImp": "중국발 자동차 수출 급증(상반기 66% 증가)에 대응한 대형 발주로, 아시아 물동량 지속에 대한 선사의 자신감과 노후선 교체 수요를 동시에 보여준다. PCTC 선복 확대 경쟁이 가속되고 있음을 시사한다.", "eImp": "The large order signals management's confidence in sustained Asian export volumes (Chinese vehicle exports up 66% in H1) and a fleet-replacement need, underscoring an accelerating race to add PCTC capacity.", "url": "https://splash247.com/hoegh-autoliners-lines-up-more-car-carriers/"}, {"code": "PCTC", "title": "Port of Rijeka welcomes first Ro-Ro vessel from China", "src": "Container News", "date": "2026-08-27", "kSum": "크로아티아 리예카항(Port of Rijeka)이 중국에서 온 첫 로로선 AICC 후앙후(AICC Huanghu)를 로로 터미널에서 맞이했다. 이 항만은 이번 기항이 자동차 물류와 국제 교역의 관문으로서 리예카의 역할 확대를 보여준다고 밝혔다.", "eSum": "The Port of Rijeka welcomed AICC Huanghu, the first Ro-Ro vessel to arrive at its terminal from China, marking a new China-Europe automotive connection. The port said the call highlights its growing role as a gateway for automotive logistics on the Adriatic with access to Central European markets.", "kImp": "중국산 자동차의 유럽 진입 경로가 지중해·아드리아해 항만으로 다변화되고 있음을 보여주며, 유럽 자동차 해상물류 지형 변화를 시사한다.", "eImp": "It shows Chinese vehicle exports diversifying their European entry points into Adriatic/Mediterranean gateways, reshaping automotive ocean-logistics routing into Europe.", "url": "https://container-news.com/port-of-rijeka-welcomes-first-ro-ro-vessel-from-china/"}, {"code": "PCTC", "title": "Three US-based RoRo operators awarded new Joint Global Sealift Charter contracts", "src": "Shippax", "date": "2026-08-25", "kSum": "미 수송사령부(USTRANSCOM)가 7개 상업 해운사에 로로·다목적·차량운반선(PCTC 포함)을 활용하는 합동 글로벌 시리프트 차터(Joint Global Sealift Charter) 계약을 부여했다. 로로/PCTC 운영사로는 ARC(American Roll-On Roll-Off Carrier), 파렐라인(Farrell Lines), 리버티글로벌로지스틱스(Liberty Global Logistics)가 포함됐다.", "eSum": "USTRANSCOM awarded a Joint Global Sealift Charter to seven commercial shipping firms, providing short-term dry-cargo charters using RoRo, multi-purpose and vehicle carriers including PCTCs. RoRo/PCTC operators American Roll-On Roll-Off Carrier, Farrell Lines and Liberty Global Logistics are among the awardees, under a 1 Sept 2026–31 Aug 2031 IDIQ deal valued up to $2.7bn.", "kImp": "미군 전략 해상수송의 상당 부분을 담당하는 대형 장기 차터로, 미국계 로로·PCTC 운영사의 안정적 물량 확보와 시장 지위를 강화한다.", "eImp": "The multi-year charter, covering a major share of US strategic sealift, secures stable volumes and market standing for US-flag RoRo/PCTC operators.", "url": "https://www.shippax.com/en/news/three-us-based-roro-operators-awarded-new-joint-global-sealift-charter-contracts.aspx"}, {"code": "PCTC", "title": "Sallaum Lines launches European automotive logistics company", "src": "Container News", "date": "2026-08-21", "kSum": "살라움 라인스(Sallaum Lines)가 리투아니아에 본사를 둔 유럽 완성차 내륙물류 전담회사 살라움 로지스틱스(Sallaum Logistics Ltd)를 출범시켰다. 초기 트럭·트레일러 50대로 시작해 2029년까지 자가 트럭 300대로 확대할 계획이며, 독일·벨기에·네덜란드 등 8개국에서 운영한다.", "eSum": "Sallaum Lines has launched Sallaum Logistics Ltd, a Lithuania-headquartered European automotive road-logistics company extending its ocean vehicle network inland. It starts with 50 truck-and-trailer units, targets 300 owned trucks by 2029, and will operate across Germany, Belgium, the Netherlands and five other markets, building on Port of Antwerp operations.", "kImp": "해상 자동차운송사가 항만-딜러 구간 내륙 물류까지 통합하는 '포트투도어' 전략으로, 완성차 물류의 수직계열화 흐름을 보여준다.", "eImp": "It reflects a port-to-door vertical-integration trend, with an ocean car carrier extending into inland finished-vehicle logistics to offer manufacturers a single accountable partner.", "url": "https://container-news.com/sallaum-lines-launches-european-automotive-logistics-company/"}, {"code": "PCTC", "title": "Hoegh Autoliners revenue up, profit down in Q2 amid shipping disruptions", "src": "Baird Maritime", "date": "2026-08-20", "kSum": "회그 오토라이너스(Höegh Autoliners)의 2026년 2분기 매출은 3.76억 달러로 전분기 대비 증가했으나, 연료·항해·용선비 상승으로 EBITDA는 1.22억 달러, 세후순이익은 8,600만 달러로 감소했다. 운송량은 400만㎥로 2.6% 늘었고, 선대 44척은 전량 가동됐다.", "eSum": "Höegh Autoliners posted Q2 2026 revenue of $376m, up quarter-on-quarter, but operating profit (EBITDA) fell to $122m and net profit to $86m on higher fuel, voyage and charter-hire costs. Transported volume rose 2.6% to 4m cubic metres, with the 44-ship fleet fully utilised and Q3 EBITDA guided in line with Q2.", "kImp": "선복 타이트 지속에도 연료비·중동 리스크로 수익성이 눌린 모습으로, 자동차운반 시장의 강한 수요와 비용 압박이 공존함을 보여준다.", "eImp": "Despite tight capacity, cost pressure from fuel and Middle East disruption squeezed margins, illustrating the coexistence of strong car-carrier demand and rising costs.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/hoegh-autoliners-revenue-up-profit-down-in-q2-amid-shipping-disruptions"}, {"code": "PCTC", "title": "New governance body launched to oversee GHG emissions data in RoRo shipping", "src": "Shippax", "date": "2026-08-20", "kSum": "글로벌 로로 커뮤니티(Global Ro-Ro Community, GRC)가 배출 데이터 관리를 감독할 새 거버넌스 기구인 GRC 카운슬(GRCC)을 설립했다. 이 협의체는 세계 자동차운반 수송 능력의 약 80%를 대표하는 부문의 GHG 산정 방법론을 유지·개선하는 역할을 맡는다.", "eSum": "The Global Ro-Ro Community (GRC) has established the GRC Council (GRCC), a new governance body to oversee emissions data management for a sector representing roughly 80% of global car-carrier transport capacity. The council maintains and improves the coalition's GHG accounting methodology, with ClassNK as independent verifier.", "kImp": "표준화된 배출 산정 체계 강화는 화주·규제당국의 공급망 탈탄소 요구에 대한 자동차운반 업계의 대응으로, 향후 화물 배정과 규제 대응에 영향을 미친다.", "eImp": "Strengthened standardised emissions accounting is the car-carrier sector's response to shipper and regulator decarbonisation demands, with implications for future cargo allocation and compliance.", "url": "https://www.shippax.com/en/news/new-governance-body-launched-to-oversee-ghg-emissions-data-in-roro-shipping.aspx"}, {"code": "PCTC", "title": "New RoRo vessel SKIPANES delivered to Smyril Line", "src": "Shippax", "date": "2026-08-25", "kSum": "스미릴 라인(Smyril Line)이 중국 옌타이 CIMC 래플스(CIMC Raffles) 조선소에서 신조 로로 화물선 스키파네스(SKIPANES)를 인도받았다. 스키파네스와 자매선 아크라네스(AKRANES)는 스미릴 라인의 로로 화물 선대를 구성한다.", "eSum": "Smyril Line has taken delivery of its new RoRo freight vessel SKIPANES from the CIMC Raffles shipyard in Yantai, China. SKIPANES and her sister ship AKRANES form part of Smyril Line's RoRo freight fleet.", "kImp": "중국 조선소의 로로 신조 인도가 이어지는 흐름을 보여주며, 유럽 로로 화물 운영사의 선대 현대화 진전을 나타낸다.", "eImp": "The delivery adds to the run of RoRo newbuilds coming out of Chinese yards and marks continued fleet modernisation by a European RoRo freight operator.", "url": "https://www.shippax.com/en/news/new-roro-vessel-skipanes-delivered-to-smyril-line.aspx"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "Adjustment due to extraordinary dividend in Wallenius Wilhelmsen (202/26)", "src": "Nasdaq", "date": "2026-08-25", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen) 이사회는 주당 보통배당 0.37달러에 더해 주당 0.24달러의 특별배당을 지급하기로 결정했다. 배당락일(ex-date)은 2026년 8월 26일이며, 이에 따라 나스닥 파생상품시장(NASDAQ Derivatives Markets)은 WAWI 관련 옵션 및 선물·포워드 계약을 재산정한다.", "eSum": "Wallenius Wilhelmsen's board resolved to distribute an extraordinary dividend of USD 0.24 per share in addition to an ordinary dividend of USD 0.37 per share, with an ex-date of 26 August 2026. NASDAQ Derivatives Markets will re-calculate options and forwards/futures in WAWI as a result. The total H1 2026 payout is USD 0.61 per share, including a USD 100m extraordinary element.", "kImp": "이번 배당은 강한 아시아발 수요와 완전 가동 상태의 선대에 힘입은 상반기 실적을 반영하며, 회사가 견조한 유동성 속에서 주주환원을 지속하고 있음을 보여준다. 카캐리어(PCTC) 업황 호조와 재무 목표 달성 기조를 확인시켜 준다.", "eImp": "The payout signals continued strong shareholder returns backed by a solid H1 2026, with full fleet utilisation and tight RoRo capacity out of Asia. It underscores the company's robust liquidity position and confidence in the car-carrier market outlook.", "url": "https://view.news.eu.nasdaq.com/view?id=b6b67fa187446356a7aa29fce7ea582ca&lang=en"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "Hoegh Autoliners Orders Six Additional LNG Dual-Fuel Vessels", "src": "Ship & Bunker", "date": "2026-08-26", "kSum": "회그 오토라이너스(Hoegh Autoliners)가 LNG 이중연료 자동차운반선(PCTC) 6척을 추가 발주해 아우로라(Aurora)급 신조 프로그램을 18척으로 확대했다. 중국 자오상중공업(China Merchants Heavy Industry)에서 2029~2031년 인도 예정이며, 4척 옵션과 4척 슬롯 예약도 확보했다.", "eSum": "Hoegh Autoliners has ordered six additional LNG dual-fuel PCTCs, expanding its Aurora-class newbuild programme to 18 vessels. To be built by China Merchants Heavy Industry with delivery in 2029-2031, the ships carry DNV ammonia- and methanol-ready notation for future fuel conversion.", "kImp": "LNG를 전환연료로 활용하되 향후 암모니아·메탄올 개조가 가능한 설계는 선주들의 리스크 헤지 전략을 보여준다. 아우로라급은 기존 PCTC 대비 탄소배출을 최대 58% 줄인다.", "eImp": "The order shows owners hedging fuel-transition risk by choosing LNG now while keeping ammonia/methanol conversion open. The Aurora class cuts carbon emissions by up to 58% versus conventional PCTCs.", "url": "https://shipandbunker.com/news/emea/270988-hoegh-autoliners-orders-six-additional-lng-dual-fuel-vessels"}, {"code": "EE", "title": "Ethanol Wins IMO Recognition but No FuelEU Credit: WinGD", "src": "Ship & Bunker", "date": "2026-08-26", "kSum": "엔진 설계사 윈지디(WinGD)에 따르면 에탄올이 IMO 전과정평가(LCA) 지침에서 온실가스 배출계수를 승인받은 첫 바이오연료가 됐으나, FuelEU Maritime에서는 여전히 크레딧을 인정받지 못한다. 브라질산 2세대 옥수수 에탄올은 20.8 gCO2eq/MJ로 VLSFO의 4분의 1 수준으로 평가됐다.", "eSum": "According to WinGD, ethanol has become the first biofuel to win approved GHG emission factors under the IMO's lifecycle guidelines, yet earns no credit under FuelEU Maritime. Brazilian second-growth corn ethanol was rated at 20.8 gCO2eq/MJ, over four times lower than VLSFO.", "kImp": "에탄올은 EU ETS에서는 절감효과를 인정받지만 FuelEU에서는 식량작물 유래 연료 배제로 크레딧이 없어, 규제 간 불일치가 연료 선택에 영향을 준다. 다만 유럽 규제 노출 선대는 세계 선단의 약 20%에 불과하다.", "eImp": "Ethanol delivers savings under EU ETS but nothing under FuelEU because food-crop-derived fuels are excluded, highlighting a regulatory mismatch shaping fuel choices. Only about 20% of the world fleet is exposed to European emissions rules.", "url": "https://shipandbunker.com/news/world/220528-ethanol-wins-imo-recognition-but-no-fueleu-credit-wingd"}, {"code": "EE", "title": "Tsuneishi Delivers Fourth Methanol Dual-Fuel 5,900-TEU Boxship", "src": "Ship & Bunker", "date": "2026-08-26", "kSum": "츠네이시조선(Tsuneishi Shipbuilding)의 저우산(Zhoushan) 법인이 메탄올과 기존 연료를 함께 사용할 수 있는 5,900 TEU 컨테이너선 4번째 선박을 인도했다. 조선소는 대체연료선 수요가 계속 늘어날 것으로 전망했다.", "eSum": "Tsuneishi Shipbuilding's Zhoushan unit has delivered its fourth 5,900-TEU containership capable of running on methanol as well as conventional marine fuels. The shipbuilder expects demand for alternative-fuelled ships to keep growing.", "kImp": "컨테이너 부문이 메탄올 추진 신조선 발주를 주도하고 있으며, 메탄올은 상대적으로 익숙한 인프라로 취급 가능해 실용적 대체연료로 평가된다. 조선소의 연속 인도는 대체연료선 건조 역량 축적을 보여준다.", "eImp": "The container segment is leading methanol newbuild orders, and methanol is seen as practical because it can use relatively familiar infrastructure. The serial deliveries show a shipyard building up alternative-fuel construction expertise.", "url": "https://shipandbunker.com/news/apac/675971-tsuneishi-delivers-fourth-methanol-dual-fuel-5900-teu-boxship"}, {"code": "EE", "title": "Hanwha Shipping Names Alt-Fuel Ready VLCC", "src": "Ship & Bunker", "date": "2026-08-26", "kSum": "한화쉬핑(Hanwha Shipping)이 암모니아·메탄올·LNG 추진 전환이 가능한 ABS 선급 표기를 갖춘 신조 초대형원유운반선(VLCC) '엘란드라 K2(Elandra K2)'를 명명했다. 한화오션(Hanwha Ocean) 옥포조선소에서 건조되는 320,000 DWT급 3척 중 첫 번째다.", "eSum": "Hanwha Shipping has named the Elandra K2, a new VLCC with ABS notations for future use of ammonia, methanol or LNG. It is the first of three 320,000 DWT VLCCs being built at Hanwha Ocean's Okpo Shipyard, with the next two due in December 2026 and February 2027.", "kImp": "ABS Fuel Ready Level 1C 표기는 규제 변화에 따라 대체연료를 채택할 유연성을 제공한다. 다만 실제 대체연료 개조는 전 세계 선단에서 여전히 제한적이다.", "eImp": "The ABS Fuel Ready Level 1C notations give the vessel flexibility to adopt alternative fuels as regulations tighten, though actual conversions remain limited across the global fleet.", "url": "https://shipandbunker.com/news/world/222456-hanwha-shipping-names-alt-fuel-ready-vlcc"}, {"code": "EE", "title": "Cargo-Partner Cuts CO2e Emissions Through Hapag-Lloyd's Biofuel Shipping Programme", "src": "Ship & Bunker", "date": "2026-08-26", "kSum": "물류기업 카고파트너(Cargo-Partner)가 하파그로이드(Hapag-Lloyd)의 지속가능 해상연료 프로그램 '십 그린(Ship Green)'을 통해 2026년 상반기 고객 해상운송 배출량을 811톤 CO2e 줄였다. 폐기물·잔재 기반 바이오연료 259.46톤을 사용해 달성했다.", "eSum": "Logistics firm Cargo-Partner reduced its customers' ocean-freight emissions by 811 tonnes of CO2e in the first half of 2026 via Hapag-Lloyd's Ship Green programme. The savings came from 259.46 mt of waste- and residue-based marine biofuel used across Hapag-Lloyd's fleet.", "kImp": "북앤클레임(book-and-claim) 방식은 특정 선박의 물리적 연료 사용과 무관하게 검증된 배출 절감을 배분해, 화주의 실질적 탈탄소 참여를 확대한다. 공급망 배출 감축 수요 증가를 반영한다.", "eImp": "The book-and-claim mechanism allocates verified reductions regardless of which vessel physically burns the biofuel, broadening shippers' access to decarbonization. It reflects rising customer demand for practical supply-chain emissions cuts.", "url": "https://shipandbunker.com/news/world/850411-cargo-partner-cuts-co2e-emissions-through-hapag-lloyds-biofuel-shipping-programme"}, {"code": "EE", "title": "HaminaKotka Port Selects ABB for Shore Power Project", "src": "Ship & Bunker", "date": "2026-08-26", "kSum": "핀란드 하미나코트카(HaminaKotka) 항이 무살로(Mussalo) 항 컨테이너 선석 6곳에 육상전력(shore power) 시스템을 구축하기 위해 ABB를 주계약자로 선정했다. EU CEF 대체연료 인프라 기금(AFIF)에서 300만 유로 이상을 지원받았다.", "eSum": "The Port of HaminaKotka has appointed ABB as main contractor for a shore power system at six container berths in Finland's Mussalo port, allowing ships to connect to the grid instead of running engines at berth. The project secured over EUR 3 million from the EU's CEF AFIF programme.", "kImp": "2030년부터 5,000 GT 이상 컨테이너·여객선에 육상전력 또는 동등 무배출 기술 사용을 의무화하는 FuelEU Maritime에 대비한 항만 인프라 투자다. 정박 중 배출과 대기오염을 줄인다.", "eImp": "The investment prepares the port for FuelEU Maritime, which from 2030 requires container and passenger ships above 5,000 GT to use shore power or equivalent zero-emission technology at EU ports, cutting at-berth emissions.", "url": "https://shipandbunker.com/news/emea/139221-haminakotka-port-selects-abb-for-shore-power-project"}, {"code": "EE", "title": "European Energy and Mitsui Sign E-Methanol Offtake Deal with OMV", "src": "Ship & Bunker", "date": "2026-08-21", "kSum": "유러피안에너지(European Energy)와 미쓰이물산(Mitsui & Co.)이 합작사 솔라파크카쇠(SPK)를 통해 덴마크 카쇠(Kasso) 설비의 e-메탄올을 OMV에 공급하는 다년 계약을 체결했다. 연 42,000톤 규모의 이 설비에서 OMV는 네 번째 공개 오프테이커가 됐으며 첫 인도는 이미 완료됐다.", "eSum": "European Energy and Mitsui & Co. have signed a multi-year agreement, via their SPK joint venture, to supply OMV with e-methanol from the 42,000 mt/year Kasso facility in Denmark. OMV becomes the fourth publicly announced offtaker after Maersk, LEGO and Novo Nordisk, with the first delivery already completed.", "kImp": "e-메탄올은 RFNBO로 인증되며 최소 기준을 크게 상회하는 온실가스 절감을 요구해, 선박용 그린연료 공급망 확대의 신호다. 오프테이크 계약 다변화는 그린 메탄올 상용 시장 형성을 뒷받침한다.", "eImp": "The e-methanol is certified as an RFNBO requiring GHG savings well above the minimum threshold, signalling expansion of green-fuel supply chains for shipping. Diversifying offtake deals underpins the emerging commercial green-methanol market.", "url": "https://shipandbunker.com/news/emea/730843-european-energy-and-mitsui-sign-e-methanol-offtake-deal-with-omv"}, {"code": "EE", "title": "Indian Oil Breaks Ground on Bunker Fuel Storage Facility in Mauritius", "src": "Ship & Bunker", "date": "2026-08-25", "kSum": "인도 국영 인디안오일(Indian Oil Corporation)이 모리셔스 포트루이스(Port Louis) 메르루주에 27,500톤 규모 벙커연료 저장시설을 착공했다. 모리셔스 법인은 2,500만 달러를 투자하며 벙커링 역량을 확대할 계획이다.", "eSum": "India's state-owned Indian Oil Corporation has broken ground on a 27,500 mt bunker fuel storage facility at Mer Rouge, Port Louis in Mauritius. Its Mauritius unit will invest USD 25 million to expand bunker storage and bunkering capabilities.", "kImp": "홍해 우회와 중동 정세로 모리셔스 벙커 수요가 급증한 가운데, 이번 투자는 모리셔스의 해양에너지 인프라 및 블루이코노미 육성 전략을 뒷받침한다. 케이프 우회 항로 확대로 포트루이스 급유 수요가 크게 늘었다.", "eImp": "With Red Sea diversions and Middle East tensions boosting Mauritius bunker demand, the investment supports the island's maritime-energy infrastructure and Blue Economy ambitions. Port Louis demand rose sharply as vessels rerouted around the Cape of Good Hope.", "url": "https://shipandbunker.com/news/emea/584894-indian-oil-breaks-ground-on-bunker-fuel-storage-facility-in-mauritius"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "Hexagon to acquire Guidance Marine positioning business", "src": "Smart Maritime Network", "date": "2026-08-26", "kSum": "헥사곤(Hexagon)이 영국의 선박 상대측위 센서 제조사 가이던스 마린(Guidance Marine) 인수에 합의했다. 가이던스 마린의 레이더·레이저·비전·마이크로파 기반 센서는 해양플랫폼, 풍력터빈, 안벽, 타 선박에 대한 선박 위치를 측정해 동적위치제어(DP)와 근접 조종을 지원한다. 인수는 2026년 말 완료 예정이며 가이던스 마린은 헥사곤 노바텔(NovAtel) 측위 사업부에 편입된다.", "eSum": "Hexagon has agreed to acquire UK-based maritime positioning sensor manufacturer Guidance Marine, whose radar, laser, vision and microwave sensors measure a vessel's position relative to platforms, wind turbines, quaysides and other vessels for station-keeping and manoeuvring. The technology is integrated with major Dynamic Positioning (DP) systems and complements Hexagon's GNSS and assured-positioning capabilities. Completion is expected by end-2026, after which Guidance Marine joins Hexagon's NovAtel Positioning Division.", "kImp": "상대측위 기술과 GNSS·항재밍 기술이 결합되면 자율운항 및 정밀 조종 분야의 통합 측위 역량이 강화된다. 오프쇼어 에너지와 해양건설 등 정밀 위치제어 수요가 큰 분야의 디지털 항법 생태계 재편 신호다.", "eImp": "Combining relative positioning with GNSS and anti-jamming strengthens integrated positioning for autonomous and precision manoeuvring. It signals continued consolidation in the digital navigation ecosystem serving offshore energy and marine construction.", "url": "https://smartmaritimenetwork.com/2026/08/26/hexagon-to-acquire-guidance-marine-positioning-business/"}, {"code": "DIG", "title": "BASSnet Neo unifies SaaS modules with Neo update", "src": "Smart Maritime Network", "date": "2026-08-26", "kSum": "바스 소프트웨어(BASS Software)가 정비·구매·자재·프로젝트·문서관리·HSEQ 애플리케이션을 클라우드 네이티브 SaaS 플랫폼으로 통합한 새 버전의 BASSnet Neo를 출시했다. 신규 기능으로 AI 기반 검색·채팅과 OCR 송장 처리가 추가됐으며, 호스팅·보안·업데이트를 공급사가 관리해 고객의 IT 인프라 부담을 줄인다. 클라우드 네이티브 구조로 지속적 업데이트와 API 연동을 지원한다.", "eSum": "BASS Software has released a new version of BASSnet Neo, combining its Maintenance, Procurement, Materials, Projects, Document Management and HSEQ applications into a single cloud-native SaaS platform for shipowners and managers. New features include AI-powered search and chat and OCR invoice processing, with the vendor managing hosting, security and updates. The architecture supports continuous updates and API integrations across the connected apps.", "kImp": "선박관리 소프트웨어의 레거시 웹 구조에서 클라우드 네이티브 SaaS로의 전환은 사이버보안·확장성·AI 대응력을 높이고 유지보수 비용을 낮춘다. 선주·관리사의 디지털 운영 통합 흐름을 보여준다.", "eImp": "The shift from legacy web architecture to cloud-native SaaS improves cybersecurity, scalability and AI-readiness while cutting maintenance overhead. It reflects the trend toward integrated, data-driven ship management platforms.", "url": "https://smartmaritimenetwork.com/2026/08/26/bassnet-neo-unifies-saas-modules-with-neo-update/"}, {"code": "DIG", "title": "Mapsea puts 150 billion trajectory records behind AI-powered S-100 ECDIS push", "src": "The Digital Ship", "date": "2026-08-26", "kSum": "맵시(Mapsea)가 한국의 2026 스케일업 팁스(Scale-up TIPS) 프로그램을 통해 수백만 달러 규모의 R&D 자금을 확보하고 AI 기반 S-100 ECDIS 개발을 추진한다. 이 시스템의 경로 엔진은 1,500억 건의 항적 기록과 기상·해류·수심·선박별 성능·연료 모델을 활용해 안전·경제성·탄소배출을 고려한 경로를 추천한다. 추천 근거를 함께 제시해 선장·육상팀이 판단할 수 있도록 설계됐다.", "eSum": "Mapsea has secured multi-million-dollar R&D funding under Korea's 2026 Scale-up TIPS programme to advance an AI-powered S-100 ECDIS for the global market. Its route engine draws on 150 billion trajectory records plus weather, currents, depth and vessel-specific performance and fuel models to recommend routes based on safety, economics and carbon emissions, while showing the reasoning behind each recommendation. The work builds on an AI route engine recognised by two CES Innovation Awards and Korean Register certification.", "kImp": "차세대 전자해도(S-100)에 대규모 데이터와 설명가능한 AI를 접목해 항법 결정과 연료·배출을 연결하는 실질적 시험대를 제시한다. 한국 해양기술 스타트업의 글로벌 항법 시장 진출 사례로 주목된다.", "eImp": "It connects navigation decisions with fuel and emissions through explainable AI on next-generation S-100 charts, offering a practical test of AI at sea. It also highlights a Korean maritime-tech push into the global navigation market.", "url": "https://thedigitalship.com/news/electronics-navigation/mapsea-puts-150-billion-trajectory-records-behind-ai-powered-s-100-ecdis-push/"}, {"code": "DIG", "title": "Eastern Pacific Shipping expands Orca AI rollout after 48% drop in close encounters", "src": "The Digital Ship", "date": "2026-08-26", "kSum": "이스턴 퍼시픽 시핑(Eastern Pacific Shipping, EPS)이 5척 선박 대상 13만 해리 이상의 파일럿에서 성과를 확인하고 오르카 AI(Orca AI)를 수십 척에 추가 도입한다. 파일럿에서 1,000해리당 근접조우 사건이 48% 감소하고 최소통과거리가 10% 증가했으며, 퍼시픽 센티넬호에서는 개방수역 근접조우가 84% 줄었다. 오르카 AI의 시포드(SeaPod)는 선교에서 컴퓨터 비전으로 물표를 탐지·분류하고 플릿뷰(FleetView)는 육상팀에 항법 데이터를 제공한다.", "eSum": "Eastern Pacific Shipping (EPS) is expanding Orca AI across dozens of additional vessels after a five-ship pilot covering more than 130,000 nautical miles. The pilot showed a 48% reduction in close-encounter events per 1,000 nautical miles and a 10% increase in average minimum passing distance, with open-water close encounters on the Pacific Sentinel falling 84%. Orca AI's SeaPod uses onboard computer vision to detect and classify objects, including targets absent from AIS, while its FleetView platform supports shore-based review and training.", "kImp": "측정 가능한 운항 데이터를 근거로 AI 상황인식 도구를 함대 규모로 확대한 사례로, 디지털 항법 도입의 실효성 판단 기준을 제시한다. 선원 중심의 안전 의사결정 지원 방향을 보여준다.", "eImp": "It shows a fleet-scale AI adoption justified by measurable operational outcomes, setting a benchmark for judging digital navigation tools. The case reinforces crew-centred, data-driven safety decision support.", "url": "https://thedigitalship.com/news/electronics-navigation/eastern-pacific-shipping-expands-orca-ai-rollout-after-48-drop-in-close-encounters/"}, {"code": "DIG", "title": "ClassNK launches AI assistant for survey operations", "src": "Smart Maritime Network", "date": "2026-08-25", "kSum": "일본선급(ClassNK)이 선급 검사 관련 정보를 찾도록 돕는 AI 어시스턴트 서베이 컴퍼스(Survey Compass)를 출시했다. 자연어 질문을 받아 검사 관련 문서를 검색하고 요약과 함께 근거 원문 링크를 제공하며, 선급의 웹 포털(ClassNK Customer Hub - Ship in Service)에서 이용할 수 있다. 초기 버전은 강선 검사·건조 규칙 B편, 검사 지침, 기술정보를 다룬다.", "eSum": "ClassNK has launched Survey Compass, an AI assistant that helps shipping companies find information relating to classification surveys via its Customer Hub web portal. It accepts natural-language questions, searches survey-related documents and returns a summary with links to the underlying source material. The initial version covers Part B of the Rules for the Survey and Construction of Steel Ships, survey guidance and technical information, with plans to expand to conventions and flag-State requirements.", "kImp": "환경 규제 등 검사 요건의 복잡성이 커지는 가운데, 근거 기반(source-backed) AI가 선주·관리사의 규정 접근성을 높인다. 선급 업무에 생성형 AI를 적용하는 확산 흐름을 보여준다.", "eImp": "As survey requirements grow more complex, especially around environmental compliance, source-backed AI improves regulatory access for owners and managers. It reflects the spread of generative AI into class society workflows.", "url": "https://smartmaritimenetwork.com/2026/08/25/classnk-launches-ai-assistant-for-survey-operations/"}, {"code": "DIG", "title": "SEA.AI and Anschütz bring machine vision into autonomous bridge systems", "src": "The Digital Ship", "date": "2026-08-25", "kSum": "씨에이아이(SEA.AI)와 안쉬츠(Anschütz)가 안쉬츠의 오토노믹스(Autonomics) 항법 시스템에 머신비전을 통합하는 파트너십을 맺었다. 광학·열화상 센서로 레이더와 AIS가 놓치기 쉬운 소형·무등화 물표를 탐지·분류해 기존 레이더·전자해도·AIS 기반 센서에 추가 트랙을 더한다. 오토노믹스는 당직사관의 판단을 대체하지 않는 의사결정 지원 시스템으로, 충돌·좌초 위험 평가와 COLREG 준수 조종안을 제안한다.", "eSum": "SEA.AI and Anschütz have partnered to integrate machine vision into Anschütz's Autonomics Navigation Suite, adding optical and thermal detection of small or unlit targets that radar and AIS may miss. The added sensor track supplements the system's existing radar, electronic chart and AIS inputs. Autonomics remains a decision-support system that assesses collision and grounding risks and proposes COLREG-compliant manoeuvres for confirmation by the officer on watch.", "kImp": "카메라 기반 탐지를 별도 도구가 아닌 항법 워크플로에 직접 통합함으로써 자율항법의 실용성을 높인다. 사람이 놓치는 물표를 보완해 충돌회피 신뢰성을 강화하는 방향을 제시한다.", "eImp": "Embedding camera-based detection directly into the navigation workflow, rather than as a separate tool, improves the practicality of autonomous navigation. It strengthens collision-avoidance reliability by closing sensor gaps that crews may miss.", "url": "https://thedigitalship.com/news/electronics-navigation/sea-ai-and-anschutz-bring-machine-vision-into-autonomous-bridge-systems/"}, {"code": "DIG", "title": "The third-party manager's cyber dilemma: How AESM solved it", "src": "The Digital Ship", "date": "2026-08-25", "kSum": "앵글로-이스턴 십매니지먼트(AESM)가 100개 이상 선주의 720척 이상을 관리하며 겪는 다중 선주 사이버보안 문제를 해결하기 위해 사이버아울(CyberOwl)을 함대 전반의 사이버보안 파트너로 선정했다. 기존 보안 인프라를 대체하지 않고 통합하는 방식으로, 간헐적 위성 연결에 대응하고 여러 벤더의 보안 데이터를 통합하는 해사 특화 SIEM-SOC 역량을 구축했다. 해사 운영을 이해하는 인력이 상주하는 SOC로 오탐을 줄이고 실효성 있는 사고 대응을 지향한다.", "eSum": "Anglo-Eastern Ship Management (AESM), which manages more than 720 vessels for over 100 shipowners, selected CyberOwl to standardise cyber monitoring, incident response and compliance across its fleet. Rather than rip-and-replace, CyberOwl integrates with existing security infrastructure, delivering a maritime-specific SIEM-SOC that handles intermittent connectivity and consolidates data from multiple vendors. Its SOC is staffed by analysts trained in maritime operations to reduce alert fatigue and support IMO 2021 and IACS E26/E27 compliance.", "kImp": "제3자 선박관리사가 다중 선주의 상이한 정책을 넘어 사이버 모니터링을 표준화한 사례로, 용선주·보험사·선급의 사이버 성숙도 요구에 대응하는 운영 인프라 모델을 제시한다. 사이버보안이 규제 준수를 넘어 경쟁 차별화 요소가 되고 있음을 보여준다.", "eImp": "It offers a template for third-party managers to standardise cyber monitoring across multi-owner fleets while meeting charterer, insurer and class demands for cyber maturity. Cyber security is shifting from box-ticking to a competitive differentiator in ship management.", "url": "https://thedigitalship.com/news/maritime-satellite-communications/the-third-party-managers-cyber-dilemma-how-aesm-solved-it/"}, {"code": "DIG", "title": "Inmarsat and SK telink to expand NexusWave in South Korea", "src": "Smart Maritime Network", "date": "2026-08-24", "kSum": "인마샛 마리타임(Inmarsat Maritime)과 SK텔링크(SK telink)가 한국 해운사 대상 넥서스웨이브(NexusWave) 연결 서비스 확대에 합의했다. HMM, 시노코어(SINOKOR) 등이 운영하는 자동차운반선·컨테이너선·VLCC 등에 적용되며, 여러 네트워크를 결합(bonded)해 연결성을 유지하는 방식이다. 클라우드 애플리케이션, 원격 기술지원, 사이버보안, 선박 성능 모니터링을 지원한다.", "eSum": "Inmarsat Maritime and South Korean telecoms provider SK telink have agreed to expand deployment of the NexusWave connectivity service among Korean shipping companies, covering car carriers, container ships and VLCCs operated by HMM, SINOKOR and others. NexusWave bonds multiple network underlays into a single service to maintain connectivity across regions. The service supports cloud applications, remote technical support, cybersecurity and vessel performance monitoring, with ViaSat-3 integration set to add capacity.", "kImp": "고대역 결합형 연결성은 클라우드·원격지원·성능 모니터링 등 선박 디지털화의 기반 인프라다. 한국 대형 선단으로의 확대는 해운 디지털 운영의 연결성 수요 증가를 방증한다.", "eImp": "High-bandwidth bonded connectivity is the backbone infrastructure for cloud apps, remote support and performance monitoring in ship digitalization. Expansion into Korea's large fleets underlines growing connectivity demand in digital shipping operations.", "url": "https://smartmaritimenetwork.com/2026/08/24/inmarsat-and-sk-telink-to-expand-nexuswave-in-south-korea/"}, {"code": "DIG", "title": "Korea approves development of new ocean monitoring satellite", "src": "Smart Maritime Network", "date": "2026-08-25", "kSum": "한국이 2033년 발사 예정인 정지궤도 환경·해양관측 위성 천리안위성 6호(Cheonlian Satellite 6) 개발을 승인했다. 해양수산부, 우주항공청, 기후에너지환경부가 공동 기획한 이 사업은 예비타당성조사를 통과했으며, 관측 채널 확대와 해상도 개선으로 적조·유류유출·저염분수 등 해양환경 변화를 감시한다. 7년간 약 7,700억 원(약 5억5,500만 달러) 규모로 내년 착수되며 국산 하이브리드 추진 시스템도 개발한다.", "eSum": "South Korea has approved development of Cheonlian Satellite 6, a geostationary environmental and ocean observation satellite scheduled for launch in 2033, after passing a preliminary feasibility study. Jointly planned by the Ministry of Oceans and Fisheries, the Korea AeroSpace Administration and the Ministry of Climate, Energy and Environment, it will have expanded channels and improved resolution to monitor red tides, oil spills and low-salinity water. The seven-year, roughly KRW770 billion (US$555m) project begins next year and includes a domestically developed hybrid propulsion system.", "kImp": "고해상도 위성 해양관측은 오염 감시·해양정책·기후대응을 위한 핵심 데이터 인프라로, 해양 IoT·원격탐사 데이터 생태계를 확장한다. 30년 이상 축적되는 연속 관측 데이터의 정책·산업 활용 가치가 크다.", "eImp": "High-resolution satellite ocean observation is core data infrastructure for pollution monitoring, ocean policy and climate response, expanding the maritime remote-sensing and IoT data ecosystem. Over 30 years of continuous observation data carries significant policy and industry value.", "url": "https://smartmaritimenetwork.com/2026/08/25/korea-approves-development-of-new-ocean-monitoring-satellite/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "Kongsberg Maritime to Provide Technology Suite for Solstad, SBM Offshore Vessel", "src": "MarineLink", "date": "2026-08-25", "kSum": "콩스버그 마리타임(Kongsberg Maritime)이 솔스타드 오프쇼어(Solstad Offshore)와 SBM 오프쇼어가 공동 소유·운영할 신형 다목적 심해 설치·건조선에 완전 통합형 기술·장비 패키지를 공급하는 계약을 따냈다. 앵커핸들링 윈치, 동적위치제어(DP), 스러스터 제어, 항법, 자동화, 전력·에너지 패키지(배터리 저장장치 포함)와 트윈 가변피치 프로펠러(CPP) 추진이 포함되며, 자체 개발 영구자석 모터 XT140이 최초 적용된다.", "eSum": "Kongsberg Maritime has secured a contract to deliver a fully integrated suite of technology and equipment for a new multi-purpose deepwater installation and construction vessel owned by Solstad Offshore and SBM Offshore. The scope covers deck machinery, dynamic positioning, thruster control, automation, a battery-inclusive power package and twin CPP propulsion, marking the first use of its in-house XT140 permanent magnet motor.", "kImp": "추진·전력·갑판기계·자동화를 단일 공급사가 통합 제공하는 사례로, 시스템 간 협조 제어와 신뢰성·에너지 효율 확보가 기술관리 관점에서 중요하다.", "eImp": "A single-vendor integrated propulsion, power and automation package offers coordinated control and reliability gains that matter for technical operators.", "url": "https://www.marinelink.com/news/kongsberg-maritime-provide-technology-542432"}, {"code": "TECH", "title": "REINTJES Launches Hybrid Propulsion System", "src": "MarineLink", "date": "2026-08-25", "kSum": "추진 솔루션 업체 라인테스(REINTJES)가 전기 모터/발전기를 기어박스 상단에 통합한 컴팩트 하이브리드 유닛 'TME Hybrid System'을 출시했다. PTI 모드에서는 디젤엔진과 병렬 운전해 배출가스·소음을 줄이고, PTO 모드에서는 발전 및 부스팅이 가능하며 출력 범위는 40~280kW다.", "eSum": "REINTJES has launched its TME Hybrid System, a compact unit integrating an electric motor/generator directly onto the gearbox. It runs in parallel with the diesel engine (PTI) to cut emissions and noise, and can generate power or provide boosting (PTO), with a 40-280 kW power range.", "kImp": "사전 조립·사전 시험된 컴팩트 하이브리드 유닛은 설치 공수와 시운전 시간을 줄여주며, 항만·연안에서의 무배출 저소음 운항 옵션을 제공한다.", "eImp": "A pre-assembled, factory-tested hybrid unit reduces installation and commissioning effort while enabling zero-emission, low-noise operation in ports and coastal areas.", "url": "https://www.marinelink.com/news/reintjes-launches-hybrid-propulsion-542419"}, {"code": "TECH", "title": "Whitepaper Demonstrates Benefits of Thordon Bearings T-BOSS Shaftline Solution", "src": "MarineLink", "date": "2026-08-25", "kSum": "수에즈막스 원유운반선 실측 데이터를 바탕으로 한 평가 연구에서 토든 베어링(Thordon Bearings)의 무(無)선미관 T-BOSS 축계 시스템이 기존 유(油)윤활 선미관 대비 이점을 입증했다. 축 길이 단축으로 최대 660㎥의 화물공간 확보, 윤활유(약 3만3천 달러) 및 연간 운영비 절감, 프로펠러축을 빼지 않고 베어링을 점검·교체할 수 있어 드라이도킹 불필요 등이 확인됐다.", "eSum": "An evaluation study using reference data from a Suezmax tanker demonstrated the benefits of Thordon Bearings' sterntubeless T-BOSS shaftline system over a conventional oil-lubricated sterntube. Benefits include up to 660m³ extra cargo space from a shorter shaft, elimination of sterntube oil costs and annual OPEX savings, and inspection/replacement of bearings without withdrawing the propeller shaft or drydocking.", "kImp": "드라이도킹 없이 베어링 정비가 가능하고 EAL 윤활유가 불필요해 정비 다운타임과 규제 대응 비용을 줄일 수 있어 선박관리자에게 실질적 이점이 크다.", "eImp": "Enabling bearing maintenance without drydocking and removing the need for EALs cuts downtime and compliance costs, a tangible benefit for technical managers.", "url": "https://www.marinelink.com/news/whitepaper-demonstrates-benefits-thordon-542412"}, {"code": "TECH", "title": "ClassNK Launches Survey Compass AI Assistant for Ship Management", "src": "MarineLink", "date": "2026-08-25", "kSum": "한국선급(ClassNK)이 선주·선박관리회사의 검사 관련 업무를 지원하는 AI 어시스턴트 'Survey Compass'를 출시했다. 자연어 질의에 대해 선급검사 관련 문서를 직접 검색하고 출처 링크와 함께 요약을 제시하는 검색기반(retrieval) 방식으로, AI 오류 위험을 줄여 검사 준비·대응 효율을 높인다.", "eSum": "ClassNK has launched 'Survey Compass,' an AI assistant supporting shipowners and ship management companies in classification survey work. Using a retrieval-based approach, it answers natural-language questions by searching survey documents and presenting summaries with source links, reducing AI inaccuracy and easing survey preparation.", "kImp": "선급검사 준비·대응은 선박관리의 핵심 업무로, 신뢰할 수 있는 AI 검색 도구는 관리팀의 업무 부담과 오류를 줄여준다.", "eImp": "Survey preparation is core to ship management, and a reliable AI search tool cuts workload and errors for technical teams.", "url": "https://www.marinelink.com/news/classnk-launches-survey-compass-ai-542431"}, {"code": "TECH", "title": "Perfect Storm: High Bunker Prices Meet Declining Fuel Quality", "src": "MarineLink", "date": "2026-08-24", "kSum": "VPS에 따르면 2026년 1~7월 발행된 벙커 알림(Bunker Alert)이 29건으로 이미 2024년 연간 전체를 넘어섰고, 이 중 72%가 캣파인(cat-fines) 및 안정성 문제와 관련됐다. HSFO·VLSFO의 오프스펙 비율이 높아지고 ISO 8217 통과 연료라도 실사용에서 운항 손상을 유발하는 사례가 늘어, P&I 벙커 클레임이 올해 50% 증가한 것으로 보고됐다.", "eSum": "VPS reports 29 Bunker Alerts issued in January-July 2026, already exceeding all of 2024, with 72% linked to cat-fines and stability issues. Off-spec rates for HSFO and VLSFO are rising, and fuels passing ISO 8217 still cause operational damage, with one P&I Club reporting bunker-related claims up 50% this year.", "kImp": "연료 품질 저하는 엔진·기기 손상과 직결되므로, 표준 시험을 넘어선 추가 연료 시험과 선내 연료관리(정제·여과)가 기술관리의 필수 요소가 된다.", "eImp": "Declining fuel quality directly risks engine and machinery damage, making additional fuel testing and rigorous onboard fuel management essential for technical managers.", "url": "https://www.marinelink.com/news/perfect-storm-high-bunker-prices-meet-542360"}, {"code": "TECH", "title": "Conoship Adds 40-MWh Battery-Electric Option to CIP3800 Coaster", "src": "MarineLink", "date": "2026-08-20", "kSum": "코노십 인터내셔널(Conoship International)이 CIP 시리즈에 CIP3800 일반화물선의 완전 전기추진 버전을 추가하며, 기존 설계에 40MWh급 배터리 시스템을 결합했다. 연안·근해 화물선의 무배출 운항을 겨냥한 신형 설계 옵션이다.", "eSum": "Conoship International has expanded its CIP-Series with a fully battery-electric version of its CIP3800 general cargo vessel, pairing the established design with a 40-MWh battery system. The design targets zero-emission operation for short-sea and coastal cargo trades.", "kImp": "대용량 배터리 전기추진 화물선 설계는 근해 운항 선대의 탈탄소 신조 옵션을 제시하며, 기술관리 측면에서 전력·배터리 시스템 운용 역량이 요구된다.", "eImp": "A high-capacity battery-electric cargo design offers a decarbonized newbuild option for short-sea fleets, requiring new power and battery management competencies from technical teams.", "url": "https://www.marinelink.com/news/conoship-adds-mwh-batteryelectric-option-542299"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "CNOOC North Sea workers secure fresh pay rise", "src": "Splash247", "date": "2026-08-24", "kSum": "중국 국영 석유사 CNOOC(중국해양석유)의 영국 북해 사업장 근로자 100여 명이 기본급 3.25% 인상과 해상수당 600파운드 인상을 담은 새 임금협약을 승인했다. 노조 유나이트(Unite)에 따르면 일부 직군은 약 3,000파운드(4,100달러) 인상 효과를 보며 Buzzard·Scott·Golden Eagle 플랫폼의 기술직이 대상이다. 지난해 5.5% 인상 합의에 이은 후속 협약이다.", "eSum": "More than 100 workers at CNOOC's UK North Sea operations have backed a new pay deal delivering a 3.25% basic pay rise plus a GBP600 uplift in the offshore allowance, worth close to GBP3,000 ($4,100) for some, according to union Unite. It covers technicians on the Buzzard, Scott and Golden Eagle platforms and follows a larger 5.5% settlement reached last year.", "kImp": "해상 인력의 임금·단체교섭 동향을 보여주는 사례로, 노조 교섭력과 해상수당 구조가 해양 인력 처우와 유지에 미치는 영향을 시사한다.", "eImp": "Illustrates collective-bargaining momentum and the role of offshore allowances in maritime/offshore labour pay and retention.", "url": "https://splash247.com/cnooc-north-sea-workers-secure-fresh-pay-rise/"}, {"code": "HR", "title": "'Major flaws' in Phoenician-M convictions says HRAS", "src": "Seatrade Maritime News", "date": "2026-08-24", "kSum": "해양인권단체 HRAS(Human Rights at Sea)가 벌크선 Phoenician-M의 1등항해사 알리 알보카리(Ali Albokhari)와 마르코 베코바치(Marko Bekovac) 선장에 대한 튀르키예 마약 유죄판결에 중대한 절차적 결함이 있다는 심층 보고서를 냈다. 증거 관리 부실과 실제 배후 미수사 등을 지적했으며, 당국은 수감된 핀란드 선원에게 추가 수사를 어렵게 할 본국 이송을 압박하고 있다. 벌금 거부로 형기는 33년으로 늘었다.", "eSum": "Human Rights at Sea (HRAS) published a report finding serious flaws in the Turkish drug-trafficking convictions of Phoenician-M chief mate Ali Albokhari and Captain Marko Bekovac, citing due-process failures, chain-of-custody problems and uninvestigated organisers. Turkish authorities are now pressuring the imprisoned Finnish seafarer to accept a transfer that would end further investigation; his sentence has been extended to 33 years.", "kImp": "선원 형사 처벌(criminalisation)과 공정 대우 문제를 부각하는 대표 사례로, 외국 관할권 하 선원 인권 보호의 취약성을 드러낸다.", "eImp": "A flagship seafarer criminalisation/fair-treatment case underscoring crew vulnerability in foreign jurisdictions.", "url": "https://www.seatrade-maritime.com/crewing/-major-flaws-in-phoenician-m-convictions-says-hras"}, {"code": "HR", "title": "IMO calls for action as Somali pirates hold more than 90 seafarers", "src": "Seatrade Maritime News", "date": "2026-08-25", "kSum": "IMO 사무총장 아르세니오 도밍게스(Arsenio Dominguez)가 소말리아 해적에 납치된 선박 6척에 억류된 선원 90여 명의 즉각적·무조건적 석방을 촉구했다. 이들은 식수·식량·의료 접근이 제한된 상태이며, 8월 20일 제품운반선 Seamull 납치 이후 소말리아·아덴만 일대에서 해적 활동이 재확산되고 있다고 경고했다.", "eSum": "IMO Secretary-General Arsenio Dominguez demanded the immediate, unconditional release of more than 90 seafarers held captive on six ships hijacked by Somali pirates between April and August, warning they face limited access to food, water and medical support. The call followed the 20 August hijacking of the tanker Seamull amid a resurgence of piracy off Somalia and the Gulf of Aden.", "kImp": "억류 선원의 복지·안전과 가족의 고통을 부각하며, 해적 재확산이 선원 보호 체계에 새로운 부담이 됨을 보여준다.", "eImp": "Spotlights the welfare and safety of hostage crews and their families as piracy resurges, straining seafarer-protection systems.", "url": "https://www.seatrade-maritime.com/security/imo-calls-for-action-as-somali-pirates-hold-more-than-90-seafarers"}, {"code": "HR", "title": "Splash Singapore: Complexio's Matthew Talbot on workforce challenges", "src": "Splash247", "date": "2026-08-25", "kSum": "Complexio 공동대표 매튜 탤벗(Matthew Talbot)은 해운의 AI 도입이 기술보다 '인력(workforce)' 문제라며, 기업들이 도입 후 필요한 변화관리·직무 재설계·재교육·성과지표 마련을 과소평가한다고 지적했다. 일부 직무는 바뀌거나 사라질 것이며, 사람을 중심에 두고 새로운 역량 중심으로 채용해야 한다고 강조했다.", "eSum": "Complexio co-CEO Matthew Talbot argues that adopting maritime AI is a workforce challenge before a technology one, warning firms underestimate the change management, role redesign, retraining and new performance measures required after deployment. He says some jobs will change or disappear and companies must keep people at the centre and hire for new skills.", "kImp": "자동화·AI 확산 속 해운 인력의 재교육과 직무 전환, 채용 역량 재정의라는 HR 과제를 부각한다.", "eImp": "Frames AI adoption as an HR issue centred on retraining, role redesign and future skills for the maritime workforce.", "url": "https://splash247.com/splash-singapore-complexios-matthew-talbot-on-workforce-challenges/"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "RMI Investigation: Chief Officer dies after entering cargo tank", "src": "SAFETY4SEA", "date": "2026-08-26", "kSum": "마셜제도(RMI) 해사청은 1등항해사가 충분히 가스프리(gas-freeing)되지 않은 화물탱크에 진입한 뒤 쓰러져 사망한 사고 조사보고서를 발표했다. 당일 오전 대기측정을 했으나 개인용 가스검지기를 착용한 사람이 없었고, 가스프리 작업이 부적절했으며 선내·육상 모두 안전문화가 미흡했다. 선장도 적절한 조치 없이 구조를 시도하며 탱크에 진입한 것으로 확인됐다.", "eSum": "The Marshall Islands (RMI) Maritime Administrator investigated the death of a Chief Officer who collapsed inside a cargo tank after entering an inadequately gas-freed space. Atmosphere testing was done earlier but no one wore a personal gas detector, the gas-freeing was ineffective, and there was an ineffective safety culture ashore and aboard, including the Master entering the tank without precautions to attempt a rescue.", "kImp": "밀폐구역 진입은 해운에서 가장 치명적인 위험 중 하나로, 필수 대기측정·개인 가스검지기 착용·엄격한 구조 절차가 초기 사망과 구조자 2차 사망을 모두 막는 핵심 손실예방 조치임을 재확인한다.", "eImp": "Enclosed-space entry remains one of shipping's deadliest hazards; the case underscores mandatory atmosphere testing, personal gas detectors and disciplined rescue protocols to prevent both the initial casualty and would-be-rescuer fatalities.", "url": "https://safety4sea.com/rmi-investigation-chief-officer-dies-after-entering-cargo-tank/"}, {"code": "HSEQ", "title": "Lessons learned: Open the hatch!", "src": "SAFETY4SEA", "date": "2026-08-26", "kSum": "IMCA는 관리자 순회 중 승조원이 조타기실의 비상탈출 해치로 갑판에 나가려 했으나 해치가 열리지 않은 사례를 공유했다. 갑판 쪽 점검 결과 연료호스가 탈출 해치 위에 놓여 통로를 막고 있었으며, 비상시 승조원이 갇힐 수 있는 상황이었다. IMCA는 탈출로·해치·소방장비·통로를 항상 비워두고 비상탈출 설비를 시각점검이 아닌 실제 개방 시험으로 정기 확인할 것을 강조했다.", "eSum": "IMCA shared an incident where crew could not open the steering room's emergency escape hatch during a walk-around; a fuel hose had been left on top of it, blocking the route and risking crew being trapped in an emergency. IMCA stresses that escape routes, hatches, firefighting equipment and access ways must be kept clear and verified by practical testing, not just visual checks.", "kImp": "막힌 비상탈출로는 생존 가능한 사고를 치명적 사고로 바꿀 수 있으며, 탈출 해치의 정기 실제 개방시험은 저비용·고효과의 손실예방 통제 수단이다.", "eImp": "A blocked emergency escape route can turn a survivable incident into a fatal one; routine practical testing of escape hatches is a low-cost, high-value loss-prevention control.", "url": "https://safety4sea.com/lessons-learned-open-the-hatch/"}, {"code": "HSEQ", "title": "MSF: Deck hatch fastening arrangement detaches", "src": "SAFETY4SEA", "date": "2026-08-20", "kSum": "Marine Safety Forum(MSF)는 갑판 해치를 고정하던 체결 프레임이 힌지에서 떨어져 나가 탱크 내부로 약 6.8m 낙하한 사고를 소개했다. 당시 외부 협력업체 작업자가 탱크 안에서 작업 중이었고, 프레임은 작업자 약 1m 뒤에 떨어져 부상을 겨우 면했다. MSF는 해치 체결·힌지 장치의 결함을 핵심 위험요인으로 지적했다.", "eSum": "The Marine Safety Forum highlighted an incident where a fastening frame securing a deck hatch detached from its hinge and fell about 6.8 metres into a tank while an external contractor was working inside, landing roughly one metre behind the worker and narrowly avoiding injury. MSF flagged the failure of the hatch fastening/hinge arrangement as the key hazard.", "kImp": "작업자가 있는 밀폐구역으로의 낙하물은 중대 부상·사망 위험이 크며, 해치 힌지·체결부 무결성 점검과 탱크 작업 중 상부 개구부 차단 통제가 필수적이다.", "eImp": "Dropped objects into occupied enclosed spaces pose a serious injury/fatality risk; inspection of hatch hinge and fastening integrity, plus barrier controls around overhead openings during tank work, are essential.", "url": "https://safety4sea.com/msf-deck-hatch-fastening-arrangement-detaches/"}, {"code": "HSEQ", "title": "Dry bulk ship-to-ship transfers: controlling the risk", "src": "UK P&I", "date": "2026-08-26", "kSum": "UK P&I는 벌크선 등 비유조선의 선박간 이송(STS) 안전을 위한 실무 프레임워크를 제시했다. 이는 INTERCARGO가 2026년 처음 발간한 '벌크선 STS 이송 지침'을 계기로 한 것으로, 건화물 STS를 유조선 모델과 다른 고위험 독립 작업으로 규정하며 적합성 검토, 단일 공동계획, 펜더·계류, 이송 통제, 지속 감시, 실질적 작업중단 기준을 다룬다. SOLAS/ISM, COLREG, MARPOL 부속서 V, IMSBC/Grain Code 등 법적 체계와 실시간 기록 필요성도 설명한다.", "eSum": "UK P&I sets out a practical framework for safer ship-to-ship (STS) transfers involving bulk carriers, prompted by INTERCARGO's first 2026 STS guidelines for bulk carriers. It treats dry bulk STS as a distinct high-risk operation, covering compatibility checks, a single joint plan, fendering/mooring, transfer control, continuous monitoring, a genuine stop-work threshold, and the legal framework plus contemporaneous records.", "kImp": "STS 작업은 접촉손상, 계류·크레인 과부하, 매달린 화물 부상, 분진·유출·오염, 액상화 위험에 승조원과 선박을 노출시키므로, 신규 INTERCARGO 지침을 SMS에 반영하면 손실예방과 클레임 대응력이 강화된다.", "eImp": "STS operations expose crews and vessels to contact damage, mooring/crane overload, suspended-load injuries, dust/spillage/pollution and liquefaction hazards; embedding the new INTERCARGO guidance into the SMS strengthens loss prevention and the Member's claims position.", "url": "https://www.ukpandi.com/news-and-resources/news/article/dry-bulk-ship-to-ship-transfers-controlling-the-risk/"}, {"code": "HSEQ", "title": "CINS Recommendations on SP188 Lithium-Ion Batteries", "src": "UK P&I", "date": "2026-08-26", "kSum": "UK P&I는 IMDG 코드 특별규정 188(SP188)에 따라 운송되는 리튬이온 배터리에 대한 CINS의 새 권고문을 소개하며, 배터리 물량 급증으로 위험 양상이 바뀌었다고 경고했다. SP188 화물은 대개 위험물 신고나 컨테이너 표시가 없어 운송인이 배터리의 존재·수량을 알기 어렵고, 컨테이너당 배터리 총량 상한도 없다. CINS는 반복되는 오신고·포장 결함·품질 문제를 지적하며 국제그룹 등과 함께 IMO CCC-12에 공동 제안했다.", "eSum": "UK P&I reports on a new CINS recommendation paper on lithium-ion batteries shipped under Special Provision 188 (SP188) of the IMDG Code. Because SP188 shipments generally carry no dangerous-goods declaration or CTU placarding, carriers may be unaware of the presence and quantity of batteries in a container, with no cap per container; CINS flags recurring misdeclaration, packaging deficiencies and quality issues, echoing a submission to IMO CCC-12.", "kImp": "컨테이너 내 리튬이온 배터리가 드러나지 않게 축적되는 것은 화물 인수·적재계획·화재예방·비상대응의 중대한 안전 공백으로, 정확한 화물정보와 위험 가시성이 해상 화물화재 예방의 근간임을 강조한다.", "eImp": "The hidden accumulation of lithium-ion batteries in containers is a significant safety gap for cargo acceptance, stowage, fire prevention and emergency response, underscoring that accurate cargo information and hazard visibility are fundamental to preventing cargo fires at sea.", "url": "https://www.ukpandi.com/news-and-resources/news/article/cins-recommendations-on-sp188-lithium-ion-batteries/"}, {"code": "HSEQ", "title": "MCA updates MGN 381 (M+F) Air pollution: Survey and certification requirements", "src": "IIMS", "date": "2026-08-26", "kSum": "영국 해사청(MCA)은 선박 대기오염방지 규정(2008, 개정)에 따른 검사·증서 발급 요건을 다루는 MGN 381(M+F) 개정판을 발표했다. 이 지침은 신규 증서를 기존 증서 만료일이 아니라 검사 완료일로 발급할 수 있는 경우를 명확히 했다.", "eSum": "The UK MCA published an amendment to MGN 381 (M+F) covering survey and certification requirements under the Merchant Shipping (Prevention of Air Pollution from Ships) Regulations 2008 (as amended), clarifying when a new certificate may be dated from the survey completion date rather than the expiry of the existing certificate.", "kImp": "선주·운항사·검사관은 개정된 MARPOL 부속서 VI 대기오염 지침에 맞춰 검사·증서 일정을 정렬해 규정 준수를 유지하고 증서 공백이나 억류를 피해야 한다.", "eImp": "Owners, operators and surveyors must align survey/certification scheduling with the revised MARPOL Annex VI air-pollution guidance to maintain compliance and avoid certificate gaps or detentions.", "url": "https://www.iims.org.uk/mca-updates-mgn-381-mf-air-pollution-survey-and-certification-requirements/"}, {"code": "HSEQ", "title": "USCG updates reporting requirements for harassment on US vessels", "src": "SAFETY4SEA", "date": "2026-08-26", "kSum": "미국 해안경비대(USCG)는 2026 회계연도 국방수권법(NDAA)에 따른 법 개정을 반영해 미국 선적 선박 내 성적 비위·괴롭힘 신고에 관한 지침을 갱신했다. 개정 지침은 어떤 사건·불만을 누가 반드시 신고해야 하는지를 명확히 하며 선박 운항사의 의무 신고 책임을 강화했다.", "eSum": "The US Coast Guard issued updated guidance on reporting sexual misconduct and harassment aboard US-flagged vessels, following statutory changes under the NDAA for Fiscal Year 2026. The guidance clarifies which complaints and incidents must be reported and by whom, tightening mandatory reporting obligations for vessel operators.", "kImp": "더 명확하고 엄격해진 괴롭힘·비위 신고 의무는 미국 선적 선박 운항사의 준법·승조원 복지 부담을 높이며, 신고 미이행 시 규제 리스크가 발생한다.", "eImp": "Stricter, clearer harassment/misconduct reporting duties raise compliance and crew-welfare obligations for operators of US-flagged vessels, with regulatory exposure for failure to report properly.", "url": "https://safety4sea.com/uscg-updates-reporting-requirements-for-harassment-on-us-vessels/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "HMM, 원양항로 비중 낮추고 근해사업 강화…약 29조원 투자", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-21", "kSum": "HMM이 선단 확장, 환경 규제 대응, 디지털 전환 등에 약 29조원을 투자하며 글로벌 톱티어 선사로의 도약을 추진한다. 컨테이너와 벌크 사업에 2024년 수립한 중장기 전략보다 더 많은 자금을 투입하며, 변동성이 큰 원양항로 비중은 낮추고 상대적으로 안정적인 근해(인트라아시아) 사업을 강화하는 방향으로 사업 포트폴리오를 재편한다.", "eSum": "HMM will invest about KRW 29 trillion in fleet expansion, environmental compliance and digital transformation to become a global top-tier carrier. The plan commits more capital than its 2024 mid-to-long-term strategy, while rebalancing the portfolio by reducing exposure to volatile deep-sea trades and strengthening the more stable intra-Asia (near-sea) business.", "kImp": "국적 1위 컨테이너 선사의 대규모 투자·전략 수정은 국내 조선 발주, 친환경 선대 전환, 항만 물동량에 직접적인 파급 효과를 가지며 한국 해운의 중장기 경쟁력을 가늠하는 지표다.", "eImp": "As Korea's largest container line, HMM's large investment and strategic pivot directly affect domestic newbuilding orders, green fleet renewal and port volumes, signaling the mid-term competitiveness of Korean shipping.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147896"}, {"code": "KR", "title": "HMM, 동아프리카 서비스(GIA) 1개→2개 확대 개편", "src": "한국해운신문(maritimepress.co.kr)", "date": "2026-08-26", "kSum": "HMM(대표이사 최원혁)이 9월 넷째 주부터 인도와 동아프리카를 잇는 GIA(Gulf-India-East Africa) 노선을 기존 1개에서 2개로 확대 개편한다. 당초 인도 나바셰바(Nhava Sheva)와 문드라(Mundra)를 허브로 케냐·탄자니아를 연결하는 단일 서비스로 운영할 계획이었으나, 동아프리카 주요 항만의 혼잡이 지속되자 선제 대응과 정시성 향상 차원에서 서비스를 세분화했다.", "eSum": "HMM will expand its Gulf-India-East Africa (GIA) service from one to two strings from the fourth week of September. Originally a single service linking Kenya and Tanzania via the Indian hubs of Nhava Sheva and Mundra, it has been split to pre-empt persistent congestion at key East African ports and improve schedule reliability under its hub-and-spoke strategy.", "kImp": "HMM의 아프리카 피더망 확충은 신흥 성장시장 공략과 허브앤스포크 전략 강화를 보여주며, 원양 의존도를 낮추려는 노선 다변화 흐름과 맞닿아 있다.", "eImp": "Building out its African feeder network shows HMM targeting emerging growth markets and reinforcing its hub-and-spoke model, aligning with its route diversification away from deep-sea reliance.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332759"}, {"code": "KR", "title": "현대글로비스, 항공 포워딩으로 K-컬처 수출 지원", "src": "한국해운신문(maritimepress.co.kr)", "date": "2026-08-27", "kSum": "현대글로비스가 국내 뷰티·엔터테인먼트 기업 제품의 항공 운송을 맡으며 K-컬처 수출을 지원하고 있다. 미국 LA·영국 런던·네덜란드 암스테르담으로 나가는 에이피알 화장품과 미국 시카고행 SM엔터테인먼트 음반의 항공운송 계약을 수주해 수행 중이며, 포워더로서 포장·통관·선적·도착까지 전 과정을 책임진다. 미술품 등 고부가가치 소비재로 사업 영역을 넓히며 비계열 고객 기반도 확대하고 있다.", "eSum": "Hyundai Glovis is supporting K-culture exports through air freight forwarding for Korean beauty and entertainment firms. It has won and is handling contracts to air-ship APR cosmetics to Los Angeles, London and Amsterdam and SM Entertainment albums to Chicago, managing the whole chain from packing and customs to loading and delivery, while expanding into high-value goods such as artworks and growing non-affiliate clients.", "kImp": "현대글로비스가 계열 물량 의존을 넘어 고부가 항공포워딩·비계열 고객으로 다각화하는 흐름을 보여주며, K-컬처 소비재 수출 확대라는 구조적 성장 기회를 포착하고 있다.", "eImp": "It illustrates Hyundai Glovis diversifying beyond captive group cargo into high-margin air forwarding and non-affiliate clients, capturing structural growth from rising K-culture consumer exports.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332774"}, {"code": "KR", "title": "\"전쟁 특수 없이도\"…건화물선 전업 스타벌크·퍼시픽베이슨 주가 70~80% 급등", "src": "쉬핑뉴스넷(shippingnewsnet.com)", "date": "2026-08-27", "kSum": "지정학적 리스크에 따른 운임 급등 없이 순수 건화물선 사업만 하는 스타벌크(Star Bulk)와 퍼시픽베이슨(Pacific Basin)의 올해 주가가 70~80% 급등한 것으로 나타났다. 벌크 시황 회복이 실적과 주가를 끌어올린 것으로, 벌크·탱커·컨테이너 등 다각화 포트폴리오를 가진 팬오션(Pan Ocean)과 대비되는 사례로 조명됐다.", "eSum": "Pure dry-bulk operators Star Bulk and Pacific Basin have seen their share prices jump 70-80% this year without relying on war-driven freight spikes, as a recovering bulk market lifted earnings and valuations. The article contrasts them with Korea's Pan Ocean, which runs a diversified bulk, tanker and container portfolio.", "kImp": "벌크 시황 회복이 선사 밸류에이션을 크게 끌어올리는 국면임을 보여주며, 팬오션 등 국적 벌크·종합 선사의 주가 재평가 가능성을 시사한다.", "eImp": "It shows a bulk-market recovery sharply re-rating carrier valuations, hinting at potential re-rating for Korean bulk and diversified operators such as Pan Ocean.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=71769"}, {"code": "KR", "title": "벌크선 시장 全 선형 회복세…BDI 2926, FFA 시장도 강세", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-26", "kSum": "8월 중·하순 벌크선 시장이 모든 선형에서 신규 화물 유입이 늘며 회복세를 나타냈다. 8월 25일 건화물선 운임지수(BDI)는 2926으로 발표됐고, 한국해양진흥공사(KOBC)가 공표하는 한국형 건화물선 운임지수(KDCI)도 상승했다. 현물 시장 강세와 함께 선물운임(FFA) 시장도 동반 강세를 보였다.", "eSum": "Dry bulk markets recovered in the second half of August as fresh cargo demand rose across all vessel sizes. The Baltic Dry Index stood at 2,926 on 25 August, Korea's KDCI also rose, and the strength in the physical market was mirrored by firm forward freight agreement (FFA) values.", "kImp": "BDI·KDCI 동반 강세와 FFA 상승은 벌크 시황의 추세적 회복을 뒷받침하며, 팬오션·대한해운 등 국적 벌크선사의 3분기 실적 개선 기대를 높인다.", "eImp": "Simultaneous strength in the BDI/KDCI and FFAs supports a sustained bulk recovery, raising expectations for Q3 earnings gains at Korean bulk carriers such as Pan Ocean and Korea Line.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147915"}, {"code": "KR", "title": "케이조선, 유럽·중동서 5100억원 규모 석유화학제품운반선 6척 수주", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-27", "kSum": "케이조선이 유럽·중동 소재 선사와 총 6척, 약 5100억원 규모의 석유화학제품운반선 신조 계약을 최근 체결했다고 밝혔다. 계약 선박은 5만t급 석유화학제품운반선 2척과 7만4000t급 4척으로 구성됐다. 중견 조선사의 고부가 제품선 연속 수주로 수주잔량과 수익성 개선이 기대된다.", "eSum": "K Shipbuilding said it recently signed contracts worth about KRW 510 billion for six product/chemical tankers with European and Middle Eastern owners. The order comprises two 50,000-dwt and four 74,000-dwt chemical/product carriers, extending the mid-sized yard's run of higher-value tanker wins and bolstering its order book and margins.", "kImp": "빅3 외 중견 조선사의 고부가 제품운반선 수주는 국내 조선 수주 저변 확대와 친환경·고사양 선종 경쟁력을 보여준다.", "eImp": "A mid-tier yard winning high-value product tankers broadens Korea's shipbuilding order base beyond the big three and demonstrates competitiveness in higher-spec, greener vessel types.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147917"}, {"code": "KR", "title": "한화오션, 노르웨이·미국 선급서 저탄소 해양플랜트 설계 개념승인 획득", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-25", "kSum": "한화오션이 글로벌 선급 인증을 바탕으로 해양플랜트 표준화 전략을 저탄소 영역까지 확장한다. 노르웨이선급(DNV)과 미국선급(ABS)으로부터 저탄소 해양플랜트 설계에 대한 개념승인(AiP)을 획득했으며, 글로벌 에너지 기업들의 탄소 감축 목표가 강화되는 가운데 이번 인증이 향후 해양플랜트 수주 경쟁력 제고에 기여할 것으로 기대된다.", "eSum": "Hanwha Ocean is extending its offshore plant standardization strategy into the low-carbon domain, securing Approval in Principle (AiP) from Norway's DNV and the American Bureau of Shipping (ABS) for low-carbon offshore facility designs. With global energy majors tightening decarbonization targets, the certification is expected to strengthen its competitiveness for future offshore orders.", "kImp": "친환경·저탄소 해양플랜트 설계 인증 확보는 에너지 대전환 국면에서 한화오션의 고부가 해양 부문 수주 경쟁력을 강화하는 선제적 포석이다.", "eImp": "Winning low-carbon offshore design approvals positions Hanwha Ocean ahead in the energy transition, strengthening its bid competitiveness in the high-value offshore segment.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147904"}, {"code": "KR", "title": "부산항 신항 2-6단계, 국산 자동화 하역장비 34기 반입 개시", "src": "한국해운신문(maritimepress.co.kr)", "date": "2026-08-26", "kSum": "부산항만공사(BPA)는 국내 최초 완전 자동화부두인 부산항 신항 서‘컨’ 2-6단계 현장으로 국산 자동화 하역장비인 트랜스퍼 크레인(T/C, 야드 크레인) 34기의 단계적 반입을 시작했다고 밝혔다. 해당 장비는 2025년 4월부터 북항 자성대부두에서 조립·검사를 거쳤고, 8월 24일 2기의 해상운송을 완료했다. 운송은 총 17차례에 걸쳐 2027년 4월까지 진행된다.", "eSum": "Busan Port Authority (BPA) has begun the phased delivery of 34 domestically built automated transfer cranes (yard cranes) to the West Container 2-6 phase of Busan New Port, Korea's first fully automated terminal. Assembled and inspected at Jasungdae wharf in North Port since April 2025, the first two units were shipped by sea on 24 August, with deliveries continuing in 17 batches through April 2027.", "kImp": "국산 자동화 하역장비 도입은 부산항의 스마트·자동화 항만 전환과 하역장비 국산화라는 두 정책 목표를 동시에 진전시키는 상징적 사례다.", "eImp": "Deploying home-grown automated cranes advances both Busan's shift to smart/automated terminals and the localization of port equipment, a symbolic milestone for Korean port policy.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332758"}, {"code": "KR", "title": "광양시, ‘광양항-일본’ 국제 카페리 운항 사업자 모집", "src": "쉬핑뉴스넷(shippingnewsnet.com)", "date": "2026-08-27", "kSum": "광양시가 광양항과 일본을 잇는 국제 카페리 항로 개설을 위한 운항 사업자 모집에 나섰다. 여객과 화물을 함께 실어 나르는 카페리 항로를 통해 대일본 물류·관광 수요를 확충하고 광양항의 여객·복합운송 기능을 강화하려는 취지다.", "eSum": "The city of Gwangyang has launched a call for operators to run an international car-ferry route linking Gwangyang Port with Japan. The ro-pax route, carrying both passengers and freight, aims to expand Japan-bound logistics and tourism demand and to reinforce Gwangyang Port's passenger and multimodal functions.", "kImp": "광양항의 대일본 카페리 신설 추진은 컨테이너·산업항 중심이던 광양항의 기능 다변화와 지역 물류·관광 활성화를 노린 시도로 주목된다.", "eImp": "The push for a Gwangyang-Japan ferry marks an effort to diversify the traditionally container/industrial port and stimulate regional logistics and tourism.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=71766"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "호르무즈 인근서 또 유조선 피격…아프라막스 '메트로 베네시안' 무력화", "src": "Insurance Marine News", "date": "2026-08-26", "kSum": "아프라막스급 원유운반선 메트로 베네시안(Metro Venetian, IMO 1013391)이 8월 24일 페르시아만에서 미상의 발사체에 피격돼 운항 불능 상태에 빠진 것으로 그리스 언론을 통해 보도됐다. 호르무즈 해협 인근에서 잇따르는 유조선 피격은 선체(H&M) 및 전쟁위험(war risk) 담보에 대한 손해 노출과 추가보험료(AP) 부담을 키우고 있다.", "eSum": "The Aframax crude tanker Metro Venetian (IMO 1013391) was reported by Greek media to have been disabled after being struck by an unknown projectile in the Persian Gulf on 24 August. The run of tanker strikes near the Strait of Hormuz is deepening loss exposure under hull & machinery and war-risk cover and pushing up additional premiums.", "kImp": "반복되는 유조선 피격은 호르무즈 통항 전쟁위험 요율을 구조적으로 끌어올리고 선체보험 손해율을 악화시켜 해상보험 시장 전반의 경색을 심화시킨다.", "eImp": "Repeated tanker strikes structurally raise Hormuz war-risk rates and worsen hull loss ratios, tightening the broader marine insurance market.", "url": "https://insurancemarinenews.com/insurance-marine-news/another-tanker-disabled-by-projectile-strike-near-strait-of-hormuz/"}, {"code": "INS", "title": "사우디 VLCC '암잔', 얀부 인근 홍해서 피격돼 화재", "src": "Insurance Marine News", "date": "2026-08-25", "kSum": "사우디 바흐리(Bahri)가 관리하는 초대형 원유운반선(VLCC) 암잔(Amzan, IMO 9693745)이 사우디 항구도시 얀부 서쪽 약 63해리 지점에서 미상의 발사체에 피격돼 화재가 발생한 것으로 보도됐다. 홍해에서의 대형 탱커 피격은 전쟁위험·선체 담보의 대형 손해 가능성을 부각시켰다.", "eSum": "The Bahri-managed VLCC Amzan (IMO 9693745) was reported to have been struck by an unknown projectile about 63 nautical miles west of the Saudi port city of Yanbu, causing a fire on board. The hit on a large tanker in the Red Sea underscored the potential for major war-risk and hull losses.", "kImp": "국영 선사 소속 VLCC까지 피격 대상이 되면서 홍해·아라비아반도 연안 전 구간의 전쟁위험 재평가와 재보험 부담 확대가 불가피해졌다.", "eImp": "With even a state carrier's VLCC targeted, war-risk repricing across the whole Red Sea/Arabian coast and heavier reinsurance costs look unavoidable.", "url": "https://insurancemarinenews.com/insurance-marine-news/saudi-vlcc-hit-in-red-sea-off-yanbu/"}, {"code": "INS", "title": "미국, 이란 대상 신규 경제제재에 해운 부문 포함", "src": "Insurance Marine News", "date": "2026-08-26", "kSum": "미국 재무부가 이란을 겨냥한 광범위한 경제 캠페인 '오퍼레이션 이코노믹 아웃캐스트(Operation Economic Outcast)'를 발표하며 해운을 5개 표적 부문 중 하나로 지목했다. 이번 제재는 이란 석유·물류망과 연계된 선박·거래를 정조준한 것으로, 선주·보험자·재보험자의 제재 준수(컴플라이언스) 리스크를 크게 높인다.", "eSum": "The US Treasury unveiled a wide-ranging economic campaign against Iran, 'Operation Economic Outcast', naming shipping as one of five targeted sectors. The measures focus on vessels and transactions tied to Iran's oil and logistics networks, sharply raising sanctions-compliance risk for owners, insurers and reinsurers.", "kImp": "해운을 명시한 대이란 제재 확대는 선체·화물·전쟁위험 보험의 인수 심사와 담보 유지에 직접 영향을 미치며, 제재 위반 시 담보 무효 리스크를 키운다.", "eImp": "Sanctions explicitly covering shipping directly affect underwriting and cover continuity across hull, cargo and war risk, heightening the risk of cover being voided for breaches.", "url": "https://insurancemarinenews.com/insurance-marine-news/new-us-economic-sanctions-on-iran-include-shipping/"}, {"code": "INS", "title": "이란, 호르무즈 통항 규정 위반 유조선 45척 블랙리스트 지정", "src": "Insurance Marine News", "date": "2026-08-26", "kSum": "이란이 호르무즈 해협 통항 규정을 위반했다며 유조선 45척을 블랙리스트에 올렸다고 밝히면서, 탱커 업계가 진퇴양난에 놓였다. 이란의 규정을 따르면 서방 제재에, 미국·서방 규정을 따르면 이란의 보복에 노출되는 구조로, 통항 선박의 나포·억류 위험과 전쟁위험 보험 수요가 동시에 커지고 있다.", "eSum": "Iran said it had blacklisted 45 tankers for breaching its rules on crossing the Strait of Hormuz, leaving the tanker industry caught between a rock and a hard place: comply with Tehran and risk Western sanctions, or follow US/Western rules and risk Iranian retaliation. The standoff raises both detention risk and demand for war-risk cover.", "kImp": "상충하는 통항 규정은 선박 나포·억류 위험을 높여 전쟁위험·억류(detention) 담보 수요와 요율을 끌어올리고 항로 선택 자체를 보험 이슈로 만든다.", "eImp": "Conflicting transit rules increase seizure/detention risk, lifting demand and rates for war-risk and detention cover and turning routing itself into an insurance issue.", "url": "https://insurancemarinenews.com/insurance-marine-news/iran-blacklists-45-tankers-for-crossing-strait-of-hormuz/"}, {"code": "INS", "title": "토탈에너지 CEO \"VLCC 호르무즈 통과 비용 2000만 달러\"", "src": "Insurance Marine News", "date": "2026-08-26", "kSum": "파트리크 푸얀네(Patrick Pouyanne) 토탈에너지(TotalEnergies) 회장 겸 CEO는 약 200만 배럴의 원유를 실은 VLCC 한 척이 호르무즈 해협을 통과하는 데 드는 비용이 현재 약 2000만 달러 수준이라고 밝혔다. 이는 급등한 전쟁위험 추가보험료와 보안 비용이 통항 경제성을 좌우하고 있음을 보여준다.", "eSum": "TotalEnergies Chairman and CEO Patrick Pouyanne said shipping a cargo of about 2 million barrels on a VLCC through the Strait of Hormuz currently costs roughly USD 20 million. The figure highlights how surging war-risk additional premiums and security costs now dominate the economics of each transit.", "kImp": "메이저 석유기업 CEO가 밝힌 구체적 통항 비용은 전쟁위험 보험료가 원유 물류비의 핵심 변수로 부상했음을 방증하며, 요율 향방이 유가·무역 흐름에까지 파급됨을 시사한다.", "eImp": "A concrete transit cost from an oil-major CEO confirms war-risk premiums are now a key driver of crude logistics costs, with rate moves rippling into oil prices and trade flows.", "url": "https://insurancemarinenews.com/insurance-marine-news/totalenergies-ceo-puts-cost-of-getting-a-vlcc-through-soh-at-20m/"}, {"code": "INS", "title": "해상 종합동향(8/26)…흑해서 일반화물선 '볼고발트 226' 드론 공격", "src": "Insurance Marine News", "date": "2026-08-26", "kSum": "8월 26일자 해상 종합동향에 따르면, 코모로 선적 일반화물선 볼고발트 226(Volgo Balt 226, IMO 8841711)이 흑해에서 운항 중 드론 공격을 받았다. 승무원 부상은 보고되지 않았다. 흑해·홍해 등 분쟁 해역에서의 드론·발사체 공격이 화물선까지 확대되며 전쟁위험 담보 범위와 손해 노출이 넓어지고 있다.", "eSum": "In the 26 August marine round-up, the Comoros-flagged general cargo ship Volgo Balt 226 (IMO 8841711) was targeted in a drone attack while operating in the Black Sea, with no crew injuries reported. Drone and projectile attacks in conflict waters such as the Black Sea and Red Sea are now reaching cargo vessels, widening war-risk exposure.", "kImp": "탱커에 국한되던 공격이 일반화물선으로 확산되면서 벌크·잡화 선대의 전쟁위험 요율과 화물보험 심사에도 압박이 가해진다.", "eImp": "Attacks spreading from tankers to general cargo ships pressure war-risk rates for bulk/breakbulk fleets and tighten cargo-insurance underwriting.", "url": "https://insurancemarinenews.com/insurance-marine-news/marine-round-up-26th-august-2026/"}, {"code": "INS", "title": "\"중동 리스크는 영구적으로 재가격됐다\"…파라투스 구스 마제드", "src": "Splash247", "date": "2026-08-27", "kSum": "연료·운임 리스크 전문기업 파라투스(Paratus)의 구스 마제드(Gus Majed) 창업자 겸 그룹 CEO는 호르무즈 사태로 중동 해상 리스크가 '영구적으로 재가격'됐다고 진단했다. 그는 외교적 타결이 이뤄져도 선주·용선주가 학습한 '해협이 수개월간 봉쇄될 수 있다'는 교훈은 사라지지 않으며, 이는 전쟁위험 보험료·선원 계약·용선 조항·대체 수출항로 투자에 계속 반영될 것이라고 강조했다.", "eSum": "Gus Majed, founder and group CEO of fuel and freight risk specialist Paratus, argues the Hormuz crisis has 'permanently repriced' Middle East maritime risk. Even if diplomacy resolves the standoff, the lesson that the strait can close for months will remain embedded in war-risk premiums, crew terms, charter clauses and investment in alternative export routes such as Fujairah and Sohar.", "kImp": "중동 리스크의 영구적 재가격론은 전쟁위험 보험료의 구조적 상향 고착을 시사하며, 해상보험·용선·선원 시장의 장기 비용 상승 전망을 뒷받침한다.", "eImp": "The 'permanent repricing' thesis implies structurally higher war-risk premiums, supporting a long-run cost uplift across marine insurance, chartering and crewing.", "url": "https://splash247.com/splash-singapore-paratuss-gus-majed-on-how-middle-east-risk-has-been-permanently-repriced/"}, {"code": "INS", "title": "지난주 호르무즈 통항량 소폭 증가…적재 통과는 감소", "src": "Insurance Marine News", "date": "2026-08-26", "kSum": "케이플러(Kpler)의 위안 리(Yuan Li) 리스크·컴플라이언스 애널리스트 분석에 따르면, 지난주 호르무즈와 인접 초크포인트의 전체 통항량은 소폭 늘었으나 그 구성은 상반된 흐름을 보였다. 특히 화물을 실은 적재(laden) 유조선의 통과는 오히려 줄어, 선주들이 위험 구간에서 만재 항해를 회피하는 경향이 나타났다.", "eSum": "According to analysis by Kpler's junior risk & compliance analyst Yuan Li, total traffic through Hormuz and adjacent chokepoints edged higher last week, but its composition diverged: notably, laden tanker crossings fell, suggesting owners are avoiding fully loaded transits through the high-risk zone.", "kImp": "적재 통과 감소는 고위험 구간에서 손해액이 큰 만재 항해를 기피하는 리스크 회피 행태를 보여주며, 통항 데이터가 전쟁위험 요율 산정의 핵심 지표로 활용됨을 시사한다.", "eImp": "Fewer laden transits reflect risk-averse behaviour avoiding high-value loaded voyages, and show transit data becoming a key input for pricing war-risk cover.", "url": "https://insurancemarinenews.com/insurance-marine-news/small-rise-in-soh-traffic-last-week-but-laden-crossings-fell/"}, {"code": "INS", "title": "벵골만서 벌크선 '오션 위너' 침몰…2명 구조·22명 실종", "src": "Insurance Marine News", "date": "2026-08-25", "kSum": "벌크선 오션 위너(Ocean Winner, IMO 9145530)가 8월 21일 벵골만에서 전복·침몰해 승무원 22명이 실종됐다. 2명은 구명뗏목에 올라 구조됐다. 전손(total loss)에 가까운 대형 해양사고로, 선체보험·화물보험은 물론 선원 인명 관련 배상 청구로 이어질 대형 손해 사안이다.", "eSum": "The bulk carrier Ocean Winner (IMO 9145530) capsized and sank in the Bay of Bengal on 21 August, leaving 22 crew missing while two were rescued after boarding a life raft. The near-total-loss casualty is a major claim event spanning hull and cargo cover as well as crew liability.", "kImp": "전손급 벌크선 침몰은 선체·화물 보험자에 대형 손해를 안기고 사망·실종 관련 배상으로 확대되며, 노후·재래식 벌크선 안전성에 대한 인수 심사 강화를 촉발할 수 있다.", "eImp": "A near-total bulker loss burdens hull and cargo underwriters and extends into death/missing liabilities, and may tighten underwriting scrutiny of ageing conventional bulkers.", "url": "https://insurancemarinenews.com/insurance-marine-news/two-rescued-but-22-missing-after-bulk-carrier-sinks-in-bay-of-bengal/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "UK P&I, 회칙 15/26호…약관(T&C) 개정 통지", "src": "UK P&I Club(ukpandi.com)", "date": "2026-08-26", "kSum": "UK P&I 클럽이 회칙(Circular) 15/26호를 통해 클럽 약관(Terms and Conditions) 개정을 회원에게 통지했다. 담보 조건과 계약 조항의 변경 사항을 담은 공식 통지로, 회원 선주는 개정 내용을 확인해 자사 부보 조건과 준수 사항에 미치는 영향을 점검해야 한다.", "eSum": "The UK P&I Club notified members, via Circular 15/26, of amendments to the club's Terms and Conditions. As a formal notice of changes to cover conditions and contractual provisions, it requires member owners to review the amendments and assess the impact on their entry terms and compliance obligations.", "kImp": "클럽 약관 개정은 담보 범위·면책·정산 조건 등 회원의 실제 부보 조건을 직접 규정하므로, 갱신·클레임 처리 시 반드시 반영해야 할 계약상 변화다.", "eImp": "Amendments to club rules directly define members' actual cover terms—scope, exclusions and settlement—making them essential contractual changes to factor into renewals and claims handling.", "url": "https://www.ukpandi.com/news-and-resources/circulars/article/circular-15/26-notice-of-amendment-to-the-clubs-terms-and-conditions/"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "OCIMF: Sharing good-quality data can produce valuable insights to improve safety", "src": "SAFETY4SEA", "date": "2026-08-25", "kSum": "신임 OCIMF(석유회사국제해사포럼) 전무이사 돈 데이비스(Don Davis)가 단독 인터뷰에서 SIRE 2.0 시행 약 2년 이후 탱커 검사 제도의 우선순위와 비전을 제시했다. 그는 위험 기반·데이터 중심 접근, OCIMF 데이터 시스템 현대화를 통한 안전 인사이트 도출, 그리고 인적요인(Human Factors)을 기술·운항 안전과 통합하는 방향을 강조했다. 또한 선사와 선원이 검사를 단순히 통과해야 할 대상이 아니라 그 목적을 이해해야 한다고 지적했다.", "eSum": "In an exclusive interview, newly appointed OCIMF Managing Director Don Davis set out his priorities for the tanker inspection system after roughly two years of SIRE 2.0. He stressed a risk-based, data-driven approach, modernising OCIMF's data systems to extract safety insights, and integrating human factors into technical and operational safety, arguing operators and crews should understand the purpose of inspections rather than simply preparing to pass individual requirements.", "kImp": "신임 OCIMF 지도부 아래 탱커 베팅(vetting)의 방향을 보여준다. SIRE 2.0가 체크리스트식 준수에서 데이터·인적요인 중심의 보증으로 이동하면서, 선사는 서류가 아니라 절차가 선상에서 실제로 어떻게 이해·적용되는지로 평가받게 됨을 의미한다. 축적된 검사 데이터가 향후 검사 항목 및 검사관 역량 개선의 근거로 활용될 전망이다.", "eImp": "Signals the direction of tanker vetting under new OCIMF leadership: SIRE 2.0 is shifting from checklist compliance to data-driven, human-factors-centred assurance. Operators will increasingly be judged on how procedures are actually understood and applied onboard, and the accumulated inspection data will drive further refinement of the programme and inspector training.", "url": "https://safety4sea.com/cm-ocimf-sharing-good-quality-data-can-produce-valuable-insights-to-improve-safety/"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "ClassNK, AI 기반 항해 최적화 GHG 저감 검증 프로젝트 참여", "src": "Ship Management International", "date": "2026-08-24", "kSum": "일본선급(ClassNK)이 AI 기반 항해 최적화 기술을 통한 온실가스(GHG) 배출 저감 효과를 검증하는 프로젝트에 참여한다고 밝혔다. 실제 운항 데이터를 활용해 감축 성과를 제3자 관점에서 검증한다.", "eSum": "ClassNK has joined a project to verify GHG emission reduction achieved through AI-based voyage optimisation technology, using operational data for third-party verification.", "kImp": "선급이 탈탄소 기술의 성능 검증자로서 역할을 확대하고 있음을 보여준다.", "eImp": "Shows class societies expanding their role as independent verifiers of decarbonisation technology performance.", "url": "https://www.shipmanagementinternational.com/news/8sxkfyghxpf37x5-9jjxp"}, {"code": "CLASS", "title": "DNV·세계에탄올협회, 3년간 글로벌 선박연료 데이터베이스 구축", "src": "PortNews", "date": "2026-08-26", "kSum": "DNV와 세계에탄올협회(Global Ethanol Association)가 향후 3년간 해운용 연료 데이터베이스를 공동 구축하기로 했다. 에탄올 등 대체연료의 실측 데이터를 축적해 규정·성능 평가에 활용한다.", "eSum": "DNV and the Global Ethanol Association have launched a three-year initiative to build a global marine fuel database, compiling data on alternative fuels such as ethanol for regulatory and performance assessment.", "kImp": "대체연료 전환기에 선급이 표준·데이터 인프라를 주도하는 흐름을 보여준다.", "eImp": "Highlights class societies leading standards and data infrastructure during the alternative-fuel transition.", "url": "https://en.portnews.ru/news/396059/"}, {"code": "CLASS", "title": "샨동해운(Shandong Shipping) 광석운반선, 세계 최초 태양광 선급인증 취득", "src": "PortNews", "date": "2026-08-26", "kSum": "중국 선주 샨동해운(Shandong Shipping)의 광석운반선이 세계 최초로 태양광(solar) 관련 선급 인증서를 취득했다. 선상 태양광 발전 시스템의 안전성과 성능을 선급이 확인했다.", "eSum": "An ore carrier owned by China's Shandong Shipping has received a world-first solar class certificate, with the classification society confirming the safety and performance of its onboard solar power system.", "kImp": "선상 재생에너지 도입에 대한 선급 인증 체계가 실선에 적용된 첫 사례다.", "eImp": "First real-ship application of class certification for onboard renewable-energy systems.", "url": "https://en.portnews.ru/news/396060/"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "Diana trims Genco stake", "src": "Splash247", "date": "2026-08-26", "kSum": "다이애나 시핑(Diana Shipping)이 9개월간의 젠코(Genco Shipping & Trading) 인수 시도가 무산된 뒤 보유 지분 축소에 나서, 8월 21일 45만주·8월 24일 75만주 등 120만주를 매각해 약 3,206만 달러(주당 약 26.71달러)를 확보했다. 지분율은 14.4%에서 11.62%로 낮아졌다. 다이애나는 지난해 11월 주당 20.60달러로 시작해 24.80달러까지 올렸으나 젠코 이사회·주주가 방어에 성공했고, 스타불크(Star Bulk)가 8월 10일 조건부 선박거래에서 이탈하자 4일 뒤 인수를 철회했다.", "eSum": "Diana Shipping began cutting its Genco stake after its nine-month takeover collapsed, selling 1.2m shares (Aug 21 and 24) for about $32m at ~$26.71/share, reducing its holding to 11.62% from 14.4%.", "kImp": "드라이벌크 업계 최대 인수전 중 하나의 종결과 지분 정리로 건화물 M&A·자본 흐름 및 밸류에이션 기대가 재조정된다.", "eImp": "The unwind ends one of dry bulk's biggest takeover battles, recalibrating sector M&A, capital flows and valuation expectations.", "url": "https://splash247.com/diana-trims-genco-stake/"}, {"code": "COMM", "title": "Höegh Autoliners adds six car carriers at China Merchants", "src": "Seatrade Maritime", "date": "2026-08-26", "kSum": "회그 오토라이너스(Höegh Autoliners)가 이중연료 LNG·무탄소 대응 오로라급(Aurora-class) PCTC 6척을 중국 자오상중공업(China Merchants Heavy Industry, CMHI)에 추가 발주해 오로라 프로그램을 18척으로 확대했다. 인도는 2029~2031년, 옵션 4척(6개월)과 2027년 말까지 유효한 슬롯 4척을 추가로 확보해 최대 26척까지 확장 가능하다. 각 선박은 최대 9,100대 적재, 기존 대비 탄소 최대 58% 절감, DNV 암모니아·메탄올 대응 표기를 갖췄다.", "eSum": "Höegh Autoliners ordered six more dual-fuel LNG, zero-carbon-ready Aurora-class PCTCs at China Merchants (CMHI) for 2029-2031 delivery, taking its Aurora programme to 18 firm vessels and scalable to 26.", "kImp": "완성차 물류 선복 확충과 친환경 신조 추세를 보여주며 PCTC 신조 시장과 탈탄소 선대 전환 경쟁을 가늠하게 한다.", "eImp": "Signals continued PCTC newbuilding momentum and the decarbonisation-driven fleet renewal race in car-carrier shipping.", "url": "https://www.seatrade-maritime.com/shipyards/h-egh-autoliners-adds-six-car-carriers-at-china-merchants"}, {"code": "COMM", "title": "CMA CGM and Saudi Arabia to Invest $434M to Expand Jeddah Islamic Port", "src": "The Maritime Executive", "date": "2026-08-25", "kSum": "프랑스-사우디 투자 라운드테이블에서 CMA CGM과 사우디 터미널 운영사 홍해게이트웨이터미널(RSGT)이 사우디 항만청(Mawani)과 협력해 홍해 제다 이슬람 항(Jeddah Islamic Port)을 확장하기로 합의했다. 약 4억3,400만 달러가 투입돼 최첨단 신규 컨테이너 터미널을 건설하며, 사우디 해운 부문 최대 규모 외국인 직접투자 중 하나로 평가된다.", "eSum": "CMA CGM and Red Sea Gateway Terminal, with Saudi Ports Authority Mawani, signed a deal in Paris to invest about $434m expanding Jeddah Islamic Port with a new state-of-the-art container terminal.", "kImp": "홍해 정상화 기대 속 사우디 항만 인프라 확충은 향후 홍해·수에즈 물동량 회복과 지역 환적 경쟁 구도에 영향을 준다.", "eImp": "Major Red Sea port investment positions Saudi Arabia for recovering Suez volumes and regional transshipment competition.", "url": "https://maritime-executive.com/article/cma-cgm-and-saudi-arabia-to-invest-434m-to-expand-jeddah-islamic-port"}, {"code": "COMM", "title": "Hormuz shock sends Jebel Ali tumbling out of global top 30", "src": "Splash247", "date": "2026-08-26", "kSum": "알파라이너(Alphaliner) 분석에 따르면 두바이 제벨알리(Jebel Ali) 항이 호르무즈 해협 봉쇄 여파로 반년 만에 세계 컨테이너 항만 순위 10위에서 32위로 추락했다. 2분기 물동량이 전년 대비 90% 넘게 급감한 37만4,000TEU에 그쳤고, 상반기 누계는 314만TEU로 전년 동기(777만TEU)의 절반 이하였다. 아부다비 칼리파(Khalifa) 항도 50% 이상 감소해 상위 50위 밖으로 밀려났으며, UAE는 후자이라·호르파칸 육상·철도 회랑과 동부해안 터미널 개발로 호르무즈 의존도를 낮추고 있다.", "eSum": "Alphaliner data shows Dubai's Jebel Ali fell from 10th to 32nd in global boxport rankings as Hormuz disruption cut Q2 throughput over 90% y/y to 374,000 teu; H1 volume of 3.14m teu was less than half of last year, with the UAE building road/rail and east-coast alternatives.", "kImp": "호르무즈 위기가 걸프 허브 항만 물동량에 미친 구조적 타격을 정량화하며, 지역 공급망·항로 재편 가속을 시사한다.", "eImp": "Quantifies the structural hit to Gulf hub ports from the Hormuz crisis and the accelerating regional supply-chain rerouting.", "url": "https://splash247.com/hormuz-shock-sends-jebel-ali-tumbling-out-of-global-top-30/"}, {"code": "COMM", "title": "RCL returns to Huangpu-Wenchong Shipbuilding for four boxships", "src": "Seatrade Maritime", "date": "2026-08-24", "kSum": "태국 선사 RCL(Regional Container Lines)이 중국 황푸원충조선(Huangpu-Wenchong)에 컨테이너선 4척을 재차 발주하며 신조 확대에 나섰다. 아시아 역내 피더·근해 시장의 선복 수요를 반영한 움직임이다.", "eSum": "Thai carrier RCL has returned to China's Huangpu-Wenchong Shipbuilding to order four containerships, extending its newbuilding programme amid intra-Asia feeder demand.", "kImp": "근해·피더 컨테이너 신조 발주 지속은 아시아 역내 물동량 강세와 선복 확충 흐름을 보여준다.", "eImp": "Continued feeder-boxship ordering underscores robust intra-Asia demand and fleet expansion.", "url": "https://www.seatrade-maritime.com/shipyards/rcl-returns-to-huangpu-wenchong-shipbuilding-for-four-boxships"}, {"code": "COMM", "title": "Medcare linked to five-ship MR1 order in China", "src": "Splash247", "date": "2026-08-26", "kSum": "프로덕트 탱커 선주 메드케어(Medcare)가 중국 조선소에 MR1급 정제유 운반선 5척을 발주한 것으로 알려졌다. 정제유 수요와 견조한 탱커 시황을 배경으로 한 신조 확대 움직임이다.", "eSum": "Product tanker owner Medcare has been linked to an order for five MR1 clean-product tankers at a Chinese yard, adding to newbuilding activity amid firm tanker markets.", "kImp": "MR 정제유선 신조 지속은 프로덕트 탱커 선복 확충과 탱커 시황 강세 기대를 반영한다.", "eImp": "Ongoing MR product-tanker ordering reflects fleet growth and firm tanker-market expectations.", "url": "https://splash247.com/medcare-linked-to-five-ship-mr1-order-in-china/"}, {"code": "COMM", "title": "Euroseas secures two-year charter extension", "src": "Splash247", "date": "2026-08-26", "kSum": "그리스 컨테이너선 선주 유로시즈(Euroseas)가 보유 선박에 대해 2년 용선 연장 계약을 확보했다. 견조한 컨테이너 용선 시황 속에 수익 가시성을 높이는 계약으로 평가된다.", "eSum": "Greek boxship owner Euroseas has secured a two-year charter extension for one of its vessels, locking in earnings visibility amid a firm containership charter market.", "kImp": "장기 용선 확보는 강세 용선 시황에서 선주 현금흐름 안정성과 시황 신뢰를 보여준다.", "eImp": "Long charter cover signals cash-flow stability and confidence in the strong boxship charter market.", "url": "https://splash247.com/euroseas-secures-two-year-charter-extension/"}, {"code": "COMM", "title": "BW LPG India adds to ageing VLGC disposal run", "src": "Splash247", "date": "2026-08-26", "kSum": "BW LPG India가 노후 초대형 LPG선(VLGC) 매각 행렬을 이어가며 선대 정리에 나섰다. 높은 중고선가와 선대 현대화 흐름 속 노후 톤수 처분이 계속되고 있다.", "eSum": "BW LPG India is continuing to dispose of ageing VLGCs, extending a fleet-renewal-driven sell-off amid high secondhand values.", "kImp": "노후 가스선 매각 지속은 S&P 시장 활황과 선대 현대화·중고선가 강세를 반영한다.", "eImp": "Ongoing older-gas-carrier sales reflect an active S&P market and firm secondhand values driving fleet renewal.", "url": "https://splash247.com/bw-lpg-india-adds-to-ageing-vlgc-disposal-run/"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "US expands sanctions on Iran's oil and shadow-fleet networks", "src": "SAFETY4SEA", "date": "2026-08-25", "kSum": "8월 24일 미 재무부가 이란 금융망·수익원(석유 밀수, 제재 회피, 이란혁명수비대(IRGC) 연계 활동)을 겨냥한 광범위한 경제 캠페인 '경제적 아웃캐스트 작전(Operation Economic Outcast)'을 개시했다. 재무장관 스콧 베선트(Scott Bessent)는 이란과 거래를 지속하는 국가가 달러 기반 금융 시스템에서 배제될 수 있다고 경고했으며, 개인·기관·선박 60곳이 지정됐다. 여기에는 이란산 원유·석유제품을 운반한 그림자 선단(shadow fleet) 5척(Sifra, G Silver, Quantum Hope, Voyage Elite, Tela)이 포함됐다.", "eSum": "On Aug 24 the US Treasury launched 'Operation Economic Outcast', a sweeping campaign against Iran's financial networks and oil smuggling; 60 individuals, entities and vessels were designated, including five shadow-fleet tankers, with secondary-sanctions reach across Iran's shipping sector.", "kImp": "이란 해운 부문 전반에 2차 제재를 확대해 그림자 선단·중개·STS 네트워크를 압박, 유가·톤마일·컴플라이언스 리스크에 광범위한 파급을 준다.", "eImp": "Sector-wide secondary sanctions pressure shadow-fleet, broker and STS networks, with broad implications for oil flows, tonne-miles and compliance risk.", "url": "https://safety4sea.com/us-expands-sanctions-on-irans-oil-and-shadow-fleet-networks/"}, {"code": "GEO", "title": "Iran Vows to Resist Widened U.S. Sanctions, Says Washington Seeks Talks", "src": "gCaptain", "date": "2026-08-25", "kSum": "이란이 경제 고립을 노린 미국의 확대 제재에 맞서겠다고 밝히며 주요 교역국들이 압박에 저항할 것이라 자신했다. 파키스탄 군 수뇌부가 미국 메시지를 이란에 전달했고, 이란은 협상 재개 의향을 내비쳤다. 이번 신규 제재는 이란산 석유 거래를 지원하는 것으로 의심되는 중국 금융기관은 포함하지 않았으며, 호르무즈 해협 원유 통과량은 월요일 기준 하루 500만 배럴로 전쟁 전 2,000만 배럴에서 급감한 상태다.", "eSum": "Iran pledged to resist expanded US sanctions and said Washington was keen to revive talks, with Pakistan mediating; the new measures spared suspected Chinese financial institutions, while Hormuz oil transits stood at 5m bpd, down from over 20m pre-war.", "kImp": "제재 확대와 협상 재개 신호가 교차하며 유가·해상 물류 리스크와 미·중·이란 지정학 구도의 향방을 좌우한다.", "eImp": "Competing sanctions escalation and talk of renewed negotiations will shape oil prices, shipping risk and US-China-Iran geopolitics.", "url": "https://gcaptain.com/iran-vows-to-resist-widened-u-s-sanctions-says-washington-seeks-talks/"}, {"code": "GEO", "title": "Ship's Cook Survives Drone Attack, Then Dies in Attack on Rescue Vessel", "src": "The Maritime Executive", "date": "2026-08-24", "kSum": "흑해 노보로시스크·투압세 인근에서 우크라이나 드론이 곡물 운반 화물선 2척을 공격해 8명이 부상하고 1명이 사망했다. 8월 18일 투압세 앞바다에서 곡물 선적 중이던 터키 소유·산마리노 선적 'Necibe'(IMO 9548732)가 드론 공격을 받아 18명이 퇴선했으며, 첫 선박에서 구조된 요리사가 그를 구한 두 번째 선박에 대한 후속 공격으로 사망했다.", "eSum": "Ukrainian drone strikes on two grain-carrying ships off Novorossiysk/Tuapse left eight injured and one dead; the cook of the first vessel (Turkish-owned, San Marino-flagged Necibe) was rescued but killed in a later strike on the rescue ship.", "kImp": "흑해 곡물 수출항에 대한 드론 공격 지속은 선원 안전과 흑해 항로 전쟁 리스크·보험료를 크게 높인다.", "eImp": "Continued drone attacks on Black Sea grain ports sharply raise crew safety concerns and war-risk premiums on Black Sea routes.", "url": "https://maritime-executive.com/article/ship-s-cook-survives-drone-attack-then-dies-in-attack-on-rescue-vessel"}, {"code": "GEO", "title": "MSC Follows Other Container Carriers in Return to Suez Canal and Red Sea", "src": "The Maritime Executive", "date": "2026-08-25", "kSum": "MSC(Mediterranean Shipping Company)가 동서 기간항로에서 홍해·수에즈 운하 통항 재개를 고객에 공지하며, CMA CGM·머스크(Maersk)·하파그로이드(Hapag-Lloyd)에 이어 네 번째로 홍해 복귀에 나선 대형 선사가 됐다. 최신 보안·운항 여건에 대한 종합 검토를 거쳤다고 밝혔다.", "eSum": "MSC confirmed it is resuming Red Sea services and transiting the Suez Canal on its East-West routes, becoming the fourth major carrier after CMA CGM, Maersk and Hapag-Lloyd to return following a security review.", "kImp": "주요 얼라이언스의 홍해 복귀 가속은 수에즈 물동량 회복과 희망봉 우회 프리미엄 소멸, 컨테이너 운임 하방 압력을 시사한다.", "eImp": "Accelerating carrier returns to the Red Sea point to recovering Suez volumes, fading Cape premiums and downward pressure on box rates.", "url": "https://maritime-executive.com/article/msc-follows-other-container-carriers-in-reutrn-to-suez-canal-and-red-sea"}, {"code": "GEO", "title": "Turkey Braces For Potential Gas Squeeze as U.S. Targets Iran Trade", "src": "gCaptain", "date": "2026-08-25", "kSum": "미국의 우방이자 이란의 세 번째 교역국인 터키가 워싱턴의 대이란 경제 고립 위협이 현실화될 경우 주요 에너지 공급원을 잃을 위기에 놓였다. 트럼프(Trump) 대통령은 이란에 경제적 숨통을 틔워주는 국가들이 대가를 치를 것이라며 선박 등록처·석유 밀수망 등을 겨냥하겠다고 경고했다.", "eSum": "Turkey, a key US ally and Iran's third-largest trading partner, risks losing a major energy supplier if Washington makes good on threats to economically isolate Tehran, as Trump warns of consequences for countries providing Iran an economic lifeline.", "kImp": "대이란 2차 제재가 터키 등 교역국 에너지 공급과 무역 흐름에 타격을 주며 지역 무역전쟁·에너지 물류 재편 위험을 키운다.", "eImp": "Secondary sanctions threaten trading partners' energy supply and trade flows, raising the risk of regional trade-war fallout and energy-logistics realignment.", "url": "https://gcaptain.com/turkey-braces-for-potential-gas-squeeze-as-u-s-targets-iran-trade/"}, {"code": "GEO", "title": "Houthis Escalate Saudi Shipping Campaign With VLCC Strike", "src": "gCaptain", "date": "2026-08-24", "kSum": "UKMTO에 따르면 8월 24일 이른 아침 사우디 얀부 서쪽 약 63해리 해상에서 탱커가 미상의 발사체에 피격돼 갑판에 화재가 발생했다. 보안분석가는 이 선박을 사우디 선적·바흐리(Bahri) 소유 VLCC 'Amzan'(IMO 9693745)으로 확인했고, 후티(Houthi)가 대함 탄도미사일 공격을 자처했다. 사우디 연계 선박을 겨냥한 홍해 캠페인 격화의 일환이다.", "eSum": "UKMTO reported a tanker struck by a projectile ~63nm west of Yanbu on Aug 24, identified as the Saudi-flagged, Bahri-owned VLCC Amzan; the Houthis claimed the anti-ship ballistic missile strike, escalating their campaign against Saudi-linked shipping.", "kImp": "후티의 사우디 선박 겨냥 공격 격화는 홍해 정상화 기대에 역행하며 전쟁위험 보험료와 항로 보안 불확실성을 재차 끌어올린다.", "eImp": "Escalating Houthi strikes on Saudi-linked ships counter Red Sea normalisation hopes and push war-risk premiums and route uncertainty back up.", "url": "https://gcaptain.com/houthis-escalate-saudi-shipping-campaign-with-vlcc-strike/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "나비오스(Navios), 상반기 호실적 발표하며 다중선종 선대 확대 지속", "src": "Ship Management International", "date": "2026-08-25", "kSum": "나비오스(Navios)가 강한 상반기(H1) 실적을 발표하고 다중선종(multi-segment) 선대를 계속 확대하고 있다고 밝혔다. (트레이드윈즈 계열 선주·선박관리 커버리지, 유료 기사 헤드라인·요약 기준)", "eSum": "Navios has reported strong first-half results and says it continues to expand its multi-segment fleet. (Owner/ship-management coverage; headline and summary only.)", "kImp": "선주사의 실적 개선과 선대 확장 기조를 보여준다.", "eImp": "Reflects an owner's improving earnings and fleet-growth stance.", "url": "https://www.shipmanagementinternational.com/news/8sxkfyghxpf37x5-9jjxp-944a6-9kexd-b9y6g-kzrgc-ykzff-zzlx2-5heyr-2x6ll-3c6h7-lcrj7-dgrxg-dpf8d"}, {"code": "TW", "title": "그리스선주협회(UGS) 회장, IMO 탈탄소 목표에 '현실론' 촉구", "src": "Ship Management International", "date": "2026-08-25", "kSum": "그리스선주협회(UGS) 회장이 IMO 탈탄소 목표에 대해 '현실론(realism)'을 촉구했다. 연료 가용성과 기술 성숙도를 고려한 실행 가능한 경로를 강조했다.", "eSum": "The president of the Union of Greek Shipowners (UGS) has called for 'realism' in IMO decarbonisation targets, stressing feasible pathways given fuel availability and technology readiness.", "kImp": "선주 진영의 규제 대응 입장과 탈탄소 이행 부담을 보여준다.", "eImp": "Illustrates owners' stance on regulation and the burden of decarbonisation implementation.", "url": "https://www.shipmanagementinternational.com/news/8sxkfyghxpf37x5-9jjxp-944a6-9kexd-b9y6g-kzrgc-ykzff-zzlx2-5heyr-2x6ll-3c6h7-lcrj7-dgrxg-dpf8d-amc7e"}, {"code": "TW", "title": "CK허치슨(CK Hutchison), 파나마 상대 15억 달러 이상 중재 제기", "src": "Ship Management International", "date": "2026-08-21", "kSum": "CK허치슨(CK Hutchison)이 파나마를 상대로 15억 달러 이상의 손해배상을 요구하는 중재 절차를 개시했다. 항만 관련 분쟁으로, 글로벌 항만·해운 자산 소유 구조에 영향을 준다.", "eSum": "CK Hutchison has launched arbitration proceedings against Panama, seeking more than $1.5bn in damages in a ports-related dispute affecting global port and shipping asset ownership.", "kImp": "대형 항만·터미널 소유주의 지정학·법적 리스크를 부각한다.", "eImp": "Highlights geopolitical and legal risk for major port and terminal owners.", "url": "https://www.shipmanagementinternational.com/news/ek2ym4kdatehn6j-rymr5-ra77l-pfczw-k4ry3-98k7t-pm4a8-ywlnh-yta9y-xfnn6-b96ec-kt9n5-cpbw5-f4z57-aec74-2n3wz-arwk2-lmwsx-egl2k-wek8z-ab7y4-92la6-ehdkt-84k2t-yg77k-eexxp-yy4zt-sex57-xshe4-7js5h"}, {"code": "TW", "title": "ADNOC L&S, 중국서 LNG운반선 2척 추가 옵션 4.44억 달러 행사", "src": "PortNews", "date": "2026-08-26", "kSum": "아부다비 선주 ADNOC L&S가 중국 조선소에서 LNG운반선 2척에 대한 4억4400만 달러 규모의 추가 발주 옵션을 행사했다. LNG 선대 확대 전략을 이어가고 있다.", "eSum": "Abu Dhabi shipowner ADNOC L&S has exercised $444m options for two more LNG carriers in China, continuing its LNG fleet-expansion strategy.", "kImp": "중동 선주의 대규모 LNG 선대 확장 흐름을 보여준다.", "eImp": "Shows Middle Eastern owners' large-scale LNG fleet expansion.", "url": "https://en.portnews.ru/news/396067/"}, {"code": "TW", "title": "닝보해운(Ningbo Marine), 중국 건조 벌커 5척에 1.84억 달러 승인", "src": "PortNews", "date": "2026-08-26", "kSum": "중국 선주 닝보해운(Ningbo Marine)이 중국에서 건조할 벌크선 5척에 대한 1억8400만 달러 규모의 투자 계획을 승인했다.", "eSum": "Chinese shipowner Ningbo Marine has approved a $184m plan for five China-built bulk carriers.", "kImp": "중국 선주의 자국 조선소 신조 투자 확대를 보여준다.", "eImp": "Reflects Chinese owners increasing newbuilding investment at domestic yards.", "url": "https://en.portnews.ru/news/396052/"}, {"code": "TW", "title": "카포워십(Karpowership), 20년 선령 LNG운반선 'Arctic Voyager' 인수", "src": "PortNews", "date": "2026-08-26", "kSum": "터키의 부유식 발전 그룹 카포워십(Karpowership)이 선령 20년의 LNG운반선 '아크틱 보이저(Arctic Voyager)'의 매수자로 확인됐다. 발전용 선박 자산 확보 차원의 중고선 거래다.", "eSum": "Turkish floating-power group Karpowership has been named buyer of the 20-year-old LNG carrier Arctic Voyager, a secondhand deal to secure vessel assets for power generation.", "kImp": "노후 LNG선의 발전용 재활용 등 중고선 시장 동향을 보여준다.", "eImp": "Illustrates secondhand market trends, including repurposing of older LNG carriers for power generation.", "url": "https://en.portnews.ru/news/396074/"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "Iran, Oman Agree to Share Strait of Hormuz Revenue", "src": "gCaptain", "date": "2026-08-26", "kSum": "이란 군당국이 호르무즈 해협(Strait of Hormuz)을 두고 오만(Oman)과 수역 분할 및 수익 배분에 합의했다고 밝혔다. IRGC 대변인 호세인 모헤비(Hossein Mohebbi)는 '미국이 이 과정을 방해해 진전이 지연되고 있다'고 주장했다. 전날 양국 외교부 공동성명은 통항 재개를 위한 '잠정 프레임워크' 논의를 언급했으나 합의나 요금은 명시하지 않았다. 트럼프(Trump) 대통령은 '해협은 열려 있고 기뢰는 제거됐다'고 재차 주장했으나, IMO는 해협이 개방되지 않았고 기뢰 제거도 확인되지 않았다고 반박했다.", "eSum": "Iran's military said it reached a revenue- and water-sharing agreement with Oman on the Strait of Hormuz, with the IRGC blaming US obstruction for delays; a prior joint foreign-ministry statement cited an 'interim framework' without confirming a deal or fees, as Trump claimed the strait is open and mine-free while the IMO disputed this.", "kImp": "호르무즈 관리·수익 배분을 둘러싼 이란·오만·미국 3각 구도는 해협 재개 시점과 유가·탱커 운임 향방을 좌우하는 핵심 변수다.", "eImp": "The Iran-Oman-US triangle over Hormuz management and revenue is the key driver of any reopening timeline and of oil and tanker-rate direction.", "url": "https://gcaptain.com/iran-oman-agree-to-share-strait-of-hormuz-revenue/"}, {"code": "HOT", "title": "Hormuz compliance clash traps owners between Tehran and Washington", "src": "Splash247", "date": "2026-08-25", "kSum": "이란이 45척을 블랙리스트에 올리고 벌금·억류·화물 몰수를 위협하는 한편, 워싱턴은 이란의 통항 규정 준수 자체가 미국 제재를 유발할 수 있다고 경고하면서 선주들이 이란과 미국 사이에 끼였다. 이란 신설 페르시아만해협관리청(PGSA)이 주말 '비준수 선박' 명단을 공개했고, 여기에는 ADNOC L&S(8척)·바흐리(Bahri)·시노코(Sinokor)·스톨트닐센(Stolt-Nielsen)·가스로그(GasLog) 등 유명 선사 선박이 포함됐다. 미 재무부는 이란 연계 기업·개인·선박 60곳을 추가 제재했다.", "eSum": "Owners are caught between Iran—which blacklisted 45 ships and threatened fines, detention and cargo confiscation via its new PGSA—and Washington, which warned that complying with Tehran's transit regime could trigger US sanctions; the list spans ADNOC L&S, Bahri, Sinokor, Stolt-Nielsen and GasLog vessels.", "kImp": "이란·미국의 상충되는 요구가 호르무즈 통항 선주에 컴플라이언스 딜레마와 이중 리스크를 안기며 통항량 위축을 심화한다.", "eImp": "Conflicting Iranian and US demands impose a compliance dilemma and dual risk on Hormuz transiters, deepening the drop in traffic.", "url": "https://splash247.com/hormuz-compliance-clash-traps-owners-between-tehran-and-washington/"}, {"code": "HOT", "title": "OFAC warns Hormuz compliance alone may breach Iran sanctions", "src": "Seatrade Maritime", "date": "2026-08-25", "kSum": "미 해외자산통제국(OFAC)이 페르시아만해협관리청(PGSA)·페르시아만해상보험공사(PGMIC)·호르무즈세이프(Hormuz Safe) 등 제재 대상 이란 기관과의 관여는 대가 지급이 없더라도 제재·처벌 대상이 될 수 있다고 경고했다. 안전항행 보증 요구에 응답하거나 보험·서비스를 수용하는 행위도 포함된다. 지난주 호르무즈 통항은 121회로 제한적이었고, 이란 통항체계 이용 비중은 46.3%로 늘었다. 8월 24일에는 오만 인근 남부 항로에서 또 다른 탱커가 피격·기동불능 상태가 됐다.", "eSum": "OFAC warned that dealing with sanctioned Iranian bodies (PGSA, PGMIC, Hormuz Safe) over Hormuz passage—even without payment—may breach sanctions; last week saw just 121 Hormuz crossings with Iran's routing scheme at 46.3%, and another tanker was attacked and disabled off Oman on Aug 24.", "kImp": "준수 행위 자체를 제재 리스크로 규정한 OFAC 경고는 선주의 항로 선택(북·남 항로)을 더욱 곤란하게 하고 실사 부담을 키운다.", "eImp": "By treating compliance itself as a sanctions risk, OFAC further complicates owners' northern/southern route choices and raises due-diligence burdens.", "url": "https://www.seatrade-maritime.com/security/ofac-warns-hormuz-compliance-alone-may-breach-iran-sanctions"}, {"code": "HOT", "title": "Iran blacklists 45 vessels over Strait of Hormuz rules violation", "src": "SAFETY4SEA", "date": "2026-08-25", "kSum": "이란이 호르무즈 해협 통항 규정을 위반했다며 45척의 탱커를 블랙리스트에 올리고, 해당 선박과 STS(선박 간 이송) 등 작업을 수행하는 선박도 처벌 대상이 될 수 있다고 경고했다. 목록에 오른 선박은 억류·몰수·벌금 대상이 될 수 있으며, 제외를 원하는 선주는 이란 해사당국에 신청·소명해야 한다.", "eSum": "Iran blacklisted 45 tankers accused of violating its Strait of Hormuz rules, warning that vessels conducting STS transfers or other operations with them could also face penalties including detention, confiscation and fines.", "kImp": "이란의 블랙리스트·처벌 위협은 호르무즈 통항 선박에 직접적 억류·몰수 리스크를 부과하고 STS 네트워크까지 위축시킨다.", "eImp": "Iran's blacklist and penalty threats impose direct detention/confiscation risk on Hormuz transiters and chill STS networks.", "url": "https://safety4sea.com/iran-blacklists-45-vessels-over-strait-of-hormuz-rules-violation/"}, {"code": "HOT", "title": "Cost to Ship a VLCC Through Hormuz Hits $20 Million, TotalEnergies CEO Says", "src": "gCaptain", "date": "2026-08-24", "kSum": "토탈에너지스(TotalEnergies) CEO 파트릭 푸얀네(Patrick Pouyanne)는 호르무즈 해협을 통한 초대형 원유운반선(VLCC) 수송 비용이 약 2,000만 달러에 달한다고 밝혔다. 페르시아만 내부에서 배럴당 50~60달러에 원유를 사들이며, 추가 운임은 배럴당 약 10달러 수준이라고 설명했다. 이라크·카타르 등이 여전히 해협으로 원유를 수송해 글로벌 유가를 배럴당 100달러 이하로 억제하는 한편, 선주·중개상에게는 큰 수익 기회가 되고 있다.", "eSum": "TotalEnergies CEO Patrick Pouyanne said shipping a VLCC cargo through Hormuz now costs about $20m—roughly $10/barrel of extra freight—while the company buys Gulf crude at $50-60, with continued Iraqi/Qatari flows keeping global prices below $100 but offering large margins for owners and traders.", "kImp": "호르무즈 통항 프리미엄이 VLCC당 2,000만 달러에 달한다는 것은 탱커 시황·운임 급등과 위기 지속에 따른 막대한 리스크 프리미엄을 상징한다.", "eImp": "A ~$20m-per-VLCC Hormuz premium epitomises surging tanker rates and the huge risk premium embedded by the ongoing crisis.", "url": "https://gcaptain.com/cost-to-ship-a-vlcc-through-hormuz-hits-20-million-totalenergies-ceo-says/"}, {"code": "HOT", "title": "Trump Says U.S. Navy Has Cleared All Mines From Strait of Hormuz", "src": "gCaptain", "date": "2026-08-25", "kSum": "트럼프(Trump) 대통령이 화요일 미 해군이 호르무즈 해협 국제수역의 모든 기뢰를 제거·폭파했다고 선언하고, 신규 기뢰 부설 선박은 즉각 파괴하는 '무관용' 정책을 시행 중이라 밝혔다. 그러나 공동해상정보센터(JMIC)는 8월 25일 자문에서 표류·미확인 기뢰 위험이 여전하고 기뢰위험구역이 활성 상태라며 위협수준을 '심각(SEVERE)'으로 유지했다. 트럼프가 일주일 새 두 번째로 기뢰 위협 종식을 선언한 것이다.", "eSum": "Trump declared the US Navy has cleared all mines from Hormuz's international waters and imposed 'zero tolerance' on new mine-laying, but JMIC's Aug 25 advisory said drifting/uncharted mine risk persists with danger areas active, keeping the threat level SEVERE.", "kImp": "미국의 '기뢰 제거' 선언과 해상보안기관의 신중론이 충돌하며 선주의 정상운항 재개 판단과 보험·운임 리스크에 혼선을 준다.", "eImp": "The gap between US 'mines cleared' claims and cautious security assessments clouds owners' decisions on resuming normal operations and keeps insurance/rate risk elevated.", "url": "https://gcaptain.com/trump-says-u-s-navy-has-cleared-all-mines-from-strait-of-hormuz/"}, {"code": "HOT", "title": "Japan Energy Plan Seeks to Back Pipelines Bypassing Hormuz", "src": "gCaptain", "date": "2026-08-26", "kSum": "일본이 미·이란 전쟁으로 중동 원유 공급 취약성이 드러나자 호르무즈 해협을 우회하는 파이프라인 건설 지원을 담은 새 에너지 전략을 추진한다. 원유 조달처 다변화, 해상 운송비 지원, JOGMEC의 리스크 파이낸싱 강화 등이 포함되며, 다카이치(Takaichi) 총리는 연말까지 전략을 확정할 방침이다. 일본은 전쟁 전 원유의 90% 이상을 중동에 의존해왔다.", "eSum": "Japan plans to back Hormuz-bypassing pipelines under a new energy-security strategy that also diversifies oil sourcing, supports shipping costs and boosts JOGMEC risk-financing; PM Takaichi aims to finalise it by year-end, after Japan relied on the Middle East for over 90% of crude pre-war.", "kImp": "주요 수입국의 호르무즈 우회 인프라 지원은 해협 위기의 장기화·구조적 항로 재편 전망을 보여주며 중동발 원유 물류를 재편한다.", "eImp": "A major importer backing Hormuz-bypass infrastructure signals expectations of a prolonged crisis and structural rerouting of Middle East crude logistics.", "url": "https://gcaptain.com/japan-energy-plan-seeks-to-back-pipelines-bypassing-hormuz/"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "이스턴퍼시픽(EPS), 5척 시범 후 Orca AI 플랫폼 대규모 확대 배치", "src": "Smart Maritime Network", "date": "2026-08-25", "kSum": "싱가포르 선사 이스턴퍼시픽해운(Eastern Pacific Shipping, EPS)이 5척 시범운항을 마친 뒤 Orca AI의 해상 운항 플랫폼을 수십 척에 추가 배치하기로 했다. AI 기반 상황인지·항해 지원 시스템을 선대 전반으로 확대한다.", "eSum": "Eastern Pacific Shipping (EPS) is deploying Orca AI's maritime operations platform across dozens more vessels after a five-ship pilot, scaling AI-based situational awareness and navigation support fleetwide.", "kImp": "선사 주도의 AI 항해지원 시스템 실전 확대가 가속되고 있음을 보여준다.", "eImp": "Shows owner-led scale-up of AI navigation-support systems gathering pace.", "url": "https://smartmaritimenetwork.com/2026/08/25/eastern-pacific-shipping-expands-orca-ai-deployment-after-five-vessel-pilot/"}, {"code": "SYS", "title": "COSL, Kongsberg 디지털 에너지관리로 시추선 연료 50% 이상 절감", "src": "The Digital Ship", "date": "2026-08-24", "kSum": "COSL Drilling Europe가 수천 개의 데이터 포인트와 Kongsberg Maritime의 전력관리 기술을 활용해 시추설비의 연료 사용량을 절반 이상 줄였다. 디지털 에너지관리 시스템의 실측 효과를 입증했다.", "eSum": "COSL Drilling Europe has used thousands of data points and Kongsberg Maritime's power management technology to cut rig fuel use by more than 50%, demonstrating the measured impact of digital energy management.", "kImp": "선박·설비 디지털 에너지관리의 정량적 절감 효과를 보여준다.", "eImp": "Demonstrates the quantifiable savings from digital energy management on vessels and rigs.", "url": "https://thedigitalship.com/news/maritime-software/cosl-cuts-rig-fuel-use-by-more-than-50-through-digital-energy-management/"}, {"code": "SYS", "title": "Dualog, 해운 전용 협업 플랫폼 'Workspace' 출시… Slack·Teams 대체", "src": "Ship Management International", "date": "2026-08-24", "kSum": "해양 IT 기업 Dualog가 해운업 특성에 맞춰 자체 개발한 협업 플랫폼 'Workspace'를 출시했다. 선박-육상 간 저대역폭 환경에서도 안정적으로 작동하도록 설계해 Slack·Teams를 대체한다.", "eSum": "Maritime IT firm Dualog has launched Workspace, a collaboration platform it built specifically for shipping, designed to work reliably over low-bandwidth ship-shore links and replace Slack and Teams.", "kImp": "육상용 협업툴의 한계를 겨냥한 해운 특화 소프트웨어의 등장을 보여준다.", "eImp": "Shows the rise of shipping-specific software targeting the limitations of generic office collaboration tools.", "url": "https://www.shipmanagementinternational.com/news/8sxkfyghxpf37x5-9jjxp-944a6-9kexd-b9y6g-kzrgc-ykzff-zzlx2"}, {"code": "SYS", "title": "라트비아 3대 항만, 340만 유로 규모 공동 디지털 플랫폼 완성", "src": "PortNews", "date": "2026-08-26", "kSum": "라트비아 3대 항만이 324만 유로를 투입한 공동 디지털 플랫폼 구축을 완료했다. 항만 간 데이터 연계와 운영 효율화를 목표로 한다.", "eSum": "Latvia's three largest ports have completed a €3.24m shared digital platform, aimed at inter-port data integration and operational efficiency.", "kImp": "항만 운영의 공동 디지털 인프라 구축 사례로 물류 시스템 통합 흐름을 보여준다.", "eImp": "A case of shared digital infrastructure for port operations, reflecting the trend toward integrated logistics systems.", "url": "https://en.portnews.ru/news/396048/"}, {"code": "SYS", "title": "SMM 2026, 디지털트윈·선원관리 등 해양 SW 혁신 대거 공개", "src": "Cyprus Shipping News", "date": "2026-08-25", "kSum": "함부르크 SMM 2026에서 상태 감시·운항 최적화용 디지털트윈(Tototheo Global의 'Echoverse')과 선원관리 솔루션(Intellar의 'Astrolabe') 등 실무 적용 단계의 해양 소프트웨어 혁신이 대거 공개됐다.", "eSum": "SMM 2026 in Hamburg showcased maritime software innovations moving into real-world use, including Tototheo Global's Echoverse digital twin for condition monitoring and Intellar's Astrolabe crew-management solution.", "kImp": "해양 소프트웨어가 시연 단계를 넘어 실제 운영 적용으로 이동하고 있음을 보여준다.", "eImp": "Signals maritime software moving from demonstration to real-world operational deployment.", "url": "https://cyprusshippingnews.com/2026/08/25/smm-2026-world-premieres-and-maritime-innovations/"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "시너지(Synergy Marine), ICS 보고서서 '부원→사관' 경력경로 역량 강화 조명", "src": "Synergy Marine Group / ICS", "date": "2026-08-20", "kSum": "국제해운회의소(ICS) 리더십 인사이트 기고가 BIMCO/ICS 선원 인력 보고서를 토대로 부원(ratings)에서 미래 사관으로의 체계적 경력경로를 다뤘다. 시너지마린그룹(Synergy Marine Group)의 최고운영책임자(COO) 마니시 프라단(Maneesh Pradhan)이 시너지의 '스킬맵', 역량보증, 시뮬레이션 교육, 디지털·대체연료 선박 대비 인재 육성 사례로 소개됐다.", "eSum": "An ICS Leadership Insights article, drawing on the BIMCO/ICS Seafarer Workforce Report, examines structured career pathways from ratings to future officers, featuring Synergy Marine Group COO Maneesh Pradhan on Synergy's Skill Map, competency assurance and simulation-based training.", "kImp": "선박관리사의 선원 육성·역량 강화 리더십을 부각한 긍정적 커버리지다.", "eImp": "Positive coverage spotlighting a ship manager's leadership in seafarer development and competency building.", "url": "https://www.ics-shipping.org/news-item/why-shippings-next-39100-officers-are-already-onboard/"}]}]};